/** Public entry point for the data-grid-io add-on — the only module consumers should import from. */

export { exportGrid, exportRows, buildExportRows, rowsToCsv, type RowsToCsvOptions, type ExportGridOptions, type ExportOutput, type ExportCellValue, type ExportCellContext, type FormatExportCell, type ExportRowsOptions, type BuildExportRowsOptions, type ExportSource, type ExportSourceContext, type ExportProgress, type ExportResult } from "./export-grid";
export { useDataGridExport, type UseDataGridExportResult } from "./use-data-grid-export";

export { printGrid, type PrintGridOptions, type PrintGridResult, type PrintPaperSize } from "./print-grid";
export { useDataGridPrint, type UseDataGridPrintResult } from "./use-data-grid-print";
export { DataGridPrintButton, type DataGridPrintButtonProps } from "./print-button";

export { parseImportFile, DEFAULT_IMPORT_LIMITS, IMPORT_CSV_ENCODINGS, type ParsedImportFile, type ParseImportFileOptions, type ImportLimits, type CsvDelimiter, type ImportCsvEncoding, type ImportValueMode } from "./parse-import-file";
export { matchImportColumns, applyImportOptions, type ImportDefaults } from "./match-import-column";
export { buildImportedRows, IMPORT_CANCELLED_MESSAGE, type ImportColumnMapping, type BuildImportedRowsOptions, type BuildImportedRowsResult, type ImportRejectedCell, type ProcessCellFromText } from "./build-imported-rows";
export {
  useDataGridImportPreview,
  type ImportFileState,
  type ImportTargetColumn,
  type ImportErrorKey,
  type UseDataGridImportPreviewOptions,
  type BuildImportOptions,
  type ParseFile,
  type ProcessImportRows,
  type UseDataGridImportPreviewResult,
} from "./use-data-grid-import";
export { DataGridImportDialog, type DataGridImportDialogProps, type ImportContext } from "./import-dialog";
export type { CheckImport, ImportCheckAnswer } from "./import-check";

export { DataGridExportButton, type DataGridExportButtonProps } from "./export-button";
export { DataGridImportButton, type DataGridImportButtonProps } from "./import-button";

import { sanitizeFormulaCell } from "@/registry/default/components/data-grid/data-grid";
import { columnLabelText, dataIndexAt, getSelectedViewRows, groupIndexAt, isDev, isPivotColumn, keepsCheckedRows, leafViewOf, pivotCellAt, pivotCellText, type DataGridReadState } from "@/registry/default/components/data-grid/data-grid-sdk";
import { normalizeLimit } from "./normalize-limit";
import type { CsvDelimiter } from "./parse-import-file";
import {
  DEFAULT_SOURCE_MAX_BYTES,
  DEFAULT_SOURCE_MAX_ROWS,
  MAX_CELL_TEXT,
  NEVER_ABORTED,
  SLICE_ROWS,
  exportCellSize,
  exportRows,
  mapExportRow,
  resolveExportColumns,
  settlePending,
  type PendingCell,
  type ExportCell,
  type ExportCellContext,
  type ExportCellValue,
  type ExportProgress,
  type ExportResult,
  type ExportRowsOptions,
  type ExportSource,
  type ExportSourceContext,
  type FormatExportCell,
  type FormatExportCellSync,
} from "./export-source";

const BOM = String.fromCharCode(0xfeff);
const CSV_EOL = "\r\n";

/** Rows an Excel worksheet holds, header row included. */
const XLSX_MAX_ROWS = 1_048_576;

/** Cells one xlsx source export holds; the writer joins the sheet into one string. */
const XLSX_MAX_CELLS = 5_000_000;

const INVALID_SHEET_NAME = /[[\]:*?/\\]/;

export { MAX_CELL_TEXT, exportRows };

/** How an XLSX file is written: `"buffered"` builds the workbook in one call, `"stream"` serializes each slice of rows as it arrives. */
export type XlsxWriterMode = "buffered" | "stream";

/** Where an export delivers its file instead of the browser download. */
export type ExportOutput = (file: Blob, ctx: { fileName: string; format: "csv" | "xlsx"; signal: AbortSignal }) => void | Promise<void>;

/** Which rows an export covers; see {@link ExportGridOptions.scope}. */
export type ExportScope = "view" | "page" | "all" | "selection" | "checked-rows" | "ranges";

/** Column selection and cell formatting shared by every export. */
export type ExportShapeOptions<TData = unknown, TFormat = FormatExportCell<TData>> = {
  /** Header text per column id, replacing the column's label in the header row. A column without an entry keeps its label. */
  headers?: Readonly<Record<string, string>>;
  /** Column ids to export, in this order. Hidden grid columns are allowed. Default: the visible columns in view order. An unknown id throws a `RangeError` before any row is read or fetched. With `source`, the source receives the same ids as `columnIds`. */
  columns?: readonly string[];
  /** Replaces the value of each exported cell. Runs once per cell after the cell type made its text (`text` holds that default). Return `null` or `undefined` for an empty cell. CSV writes numbers and booleans as text and Dates as ISO 8601; XLSX keeps numbers, booleans and Dates typed. Without `formatCell`, XLSX writes `number`, `date`, and `checkbox` columns typed and every other column as text. A string stays text, cut at 32,767 characters. A number that is not finite and an invalid Date make an empty cell. A throw rejects the export. `exportGrid` and `buildXlsx` also accept a hook that returns a promise: they await the promises of each slice of rows together, in groups of at most 10,000 cells, and `ctx.signal` aborts with the export. Load data for many cells in `source`; use an async hook for a value that one cell needs. `buildCsv` is synchronous and throws a `TypeError` for a promise. */
  formatCell?: TFormat;
};

/** Options for {@link buildCsv}. */
export type BuildCsvOptions<TData = unknown> = ExportShapeOptions<TData, FormatExportCellSync<TData>> & {
  /** Row scope, same semantics as {@link ExportGridOptions.scope}; default 'view'. */
  scope?: ExportScope;
  /** Whether to emit a header row; default true. */
  includeHeaders?: boolean;
  /** CSV field delimiter; default ','. */
  csvDelimiter?: CsvDelimiter;
  /** Prefix the file with a UTF-8 BOM; default `true`. */
  csvBom?: boolean;
  /** Prefix formula-like cells with a single quote; default `true`. */
  sanitizeFormulas?: boolean;
  /** Same row cap as {@link ExportGridOptions.maxRows}. */
  maxRows?: number;
};

/** Options for {@link exportGrid}. */
export type ExportGridOptions<TData = unknown> = ExportShapeOptions<TData> & {
  /** Receives the finished file instead of the browser download. The grid builds no object URL. `fileName` carries the extension. A rejection rejects the export, and an aborted `signal` rejects before `output` runs. Works for loaded rows, `source`, and both formats. */
  output?: ExportOutput;
  /** 'xlsx' via lazily-imported hucre, or hand-rolled RFC4180 'csv' (default). */
  format?: "xlsx" | "csv";
  /** 'view' (default) exports the current sort/filter order, every page of a paged grid; 'page' exports only the shown page; 'all' ignores view order and exports every row in `data` order; 'selection' exports only the selected rows, in view order; 'checked-rows' exports only the checked rows; 'ranges' exports only the rows the cell ranges cover, and ignores checked rows. */
  scope?: ExportScope;
  /** Whether to emit a header row; default true. */
  includeHeaders?: boolean;
  /** CSV field delimiter; default ','. Ignored for xlsx. */
  csvDelimiter?: CsvDelimiter;
  /**
   * Prefix the CSV with a UTF-8 BOM (`\uFEFF`); default `true`. Excel only detects UTF-8 when the
   * file starts with a BOM — without it, umlauts and other non-ASCII characters open as mojibake.
   * Set `false` when a downstream consumer chokes on a leading BOM character.
   */
  csvBom?: boolean;
  /**
   * Prefix formula-like CSV cells (leading `=`, `+`, `-`, `@`, TAB, or CR; plain numbers exempt) with
   * a single quote so Excel/LibreOffice/Sheets read them as text instead of executing them;
   * default `true`. Set `false` when a downstream consumer expects the raw string.
   * XLSX exports are unaffected (string cells never run as formulas).
   */
  sanitizeFormulas?: boolean;
  /** Download file name, without extension; default 'export'. */
  fileName?: string;
  /** How XLSX is written; default `"buffered"`. `"stream"` serializes each slice of 1,000 rows to XML as it arrives and drops the cell objects. The writer keeps the serialized rows until the file is built, so peak memory stays close to `"buffered"`. The file has the same cells, cut, sheet limits, `maxBytes`, and abort checks. Ignored for csv. */
  xlsxWriter?: XlsxWriterMode;
  /** Name of the single sheet inside the xlsx file; default 'Sheet1'. Ignored for csv. An invalid Excel sheet name (empty, over 31 characters, `[]:*?/\`, a leading or trailing `'`, `history` in any case) rejects. */
  sheetName?: string;
  /** Caps the number of data rows exported (the header row is not counted); when the scope exceeds the cap, the export is truncated with a dev-only warning. With `source` the default is 1,000,000, and an xlsx file also stops at the Excel sheet limit and at 5,000,000 cells. */
  maxRows?: number;
  /** Where the rows of the whole result come from, for a grid that holds one page or some loaded blocks. With `source` the export ignores `scope` and the held rows; the grid's `spec` goes to the source. */
  source?: ExportSource;
  /** With `source`: stop after the slice of rows that passes this many bytes of file text (xlsx: characters); default 256 MiB. The export keeps what it has and reports `truncated` when more rows follow. */
  maxBytes?: number;
  /** Cancels the export. The promise rejects with the signal's reason, no file downloads, and `output` does not run. */
  signal?: AbortSignal;
  /** With `source`: called after each batch with the running totals. */
  onProgress?: (progress: ExportProgress) => void;
};

export type { ExportCell, ExportCellContext, ExportCellValue, ExportProgress, ExportResult, ExportRowsOptions, ExportSource, ExportSourceContext, FormatExportCell, FormatExportCellSync };

const NEEDS_QUOTING_DEFAULT = /["\r\n]/;

/** Quotes one RFC4180 CSV field when it contains the delimiter, a quote, or a line break; doubles internal quotes. */
export function quoteCsvField(value: string, delimiter: string): string {
  const needsQuoting = value.includes(delimiter) || NEEDS_QUOTING_DEFAULT.test(value);
  if (!needsQuoting) return value;
  return `"${value.replace(/"/g, '""')}"`;
}

/** Options for {@link rowsToCsv}. */
export type RowsToCsvOptions = {
  /** Field separator. Default `","`. */
  delimiter?: string;
  /** Prefix formula-like fields with `'` (see `sanitizeFormulaCell`). Default `true`. */
  sanitizeFormulas?: boolean;
};

/**
 * Joins rows into an RFC4180 CSV string (CRLF line endings), quoting fields as needed. With
 * `sanitizeFormulas` (default `true`), formula-like fields get a leading `'` first (see `sanitizeFormulaCell`).
 */
export function rowsToCsv(rows: readonly (readonly string[])[], options: RowsToCsvOptions = {}): string {
  const { delimiter = ",", sanitizeFormulas = true } = options;
  // sanitize before quoting: the apostrophe prefix itself never needs quoting
  const field = (value: string) => quoteCsvField(sanitizeFormulas ? sanitizeFormulaCell(value) : value, delimiter);
  return rows.map((row) => row.map(field).join(delimiter)).join("\r\n");
}

/** Options for {@link buildExportRows}. */
export type BuildExportRowsOptions = {
  /** Cell text source: `'export'` uses the cell type's `toText` (CSV/XLSX), `'display'` uses `toDisplayText ?? toText` (print). Default `'export'`. */
  text?: "export" | "display";
  /** Caps the number of data rows built (the header row is not counted). */
  maxRows?: number;
};

function checkedViewRows(selection: DataGridReadState["selection"]): number[] {
  const rows: number[] = [];
  for (const [start, end] of selection.rows.runs()) for (let row = start; row < end; row++) rows.push(row);
  return rows;
}

function rangeViewRows(selection: DataGridReadState["selection"]): number[] {
  const rows = new Set<number>();
  if (selection.current) {
    for (const { y, height } of [selection.current.range, ...selection.current.rangeStack]) for (let row = y; row < y + height; row++) rows.add(row);
  }
  return [...rows].sort((a, b) => a - b);
}

/**
 * Resolves the data indices a scope covers (lazy holes excluded): `'view'` walks the whole sorted and filtered view (every page, collapsed groups included, group rows left out)
 * (current sort/filter order), `'page'` walks the shown page only, `'all'` walks `data` as-is, `'selection'` walks only the selected
 * rows in view order.
 */
export function exportDataIndices(state: DataGridReadState, scope: ExportScope): number[] {
  const dataIndexOfViewRow = (viewRow: number) => dataIndexAt(state, viewRow) ?? -1;
  const scoped: readonly number[] =
    scope === "all"
      ? state.data.map((_, i) => i)
      : scope === "checked-rows"
        ? checkedViewRows(state.selection).map(dataIndexOfViewRow)
        : scope === "ranges"
          ? rangeViewRows(state.selection).map(dataIndexOfViewRow)
          : scope === "selection"
            ? getSelectedViewRows(state.selection, { checkedRowsOnly: keepsCheckedRows(state) }).map(dataIndexOfViewRow)
            : scope === "page"
              ? state.viewIndex
              : leafViewOf(state);
  // lazy grids keep `data` sparse and a grouped view holds group rows (entries below 0): skip both before any accessor runs
  return scoped.filter((dataRowIndex) => dataRowIndex >= 0 && state.data[dataRowIndex] !== undefined);
}

/** The rows an export builds: data indices, or under pivot the view rows of the pivot rows that hold their cells. */
type ExportRowPlan = { pivot: boolean; rows: number[] };

/** Resolves {@link ExportRowPlan} for `scope`. Under pivot every scope walks the shown rows; no pivot row is ever checked. */
export function exportRowPlan(state: DataGridReadState, scope: ExportScope): ExportRowPlan {
  if (!state.pivot) return { pivot: false, rows: exportDataIndices(state, scope) };
  const viewRows =
    scope === "checked-rows"
      ? checkedViewRows(state.selection)
      : scope === "ranges"
        ? rangeViewRows(state.selection)
        : scope === "selection"
          ? getSelectedViewRows(state.selection, { checkedRowsOnly: keepsCheckedRows(state) })
          : Array.from({ length: state.viewIndex.length }, (_, viewRow) => viewRow);
  const loaded = (viewRow: number) => {
    const groupIndex = groupIndexAt(state.viewIndex, viewRow);
    return groupIndex !== undefined && state.groupLayout?.rows[groupIndex]?.pivotCells !== undefined;
  };
  return { pivot: true, rows: viewRows.filter(loaded) };
}

/** One pivot row: the key text, then each pivot cell's text; XLSX keeps a pivot cell's number typed. Consumer cell hooks need a data row, so they do not run. */
function pivotExportRow(state: DataGridReadState, columns: readonly ExportColumn[], viewRow: number, text: "export" | "display", typed: boolean): ExportCell[] {
  return columns.map((column) => {
    const cell = typed ? pivotCellAt(state, viewRow, column) : undefined;
    return typeof cell === "number" ? cell : (pivotCellText(state, viewRow, column, text) ?? "");
  });
}

function buildPlanRows<TData>(state: DataGridReadState, plan: ExportRowPlan, text: "export" | "display", columns: readonly ExportColumn[], formatCell: FormatExportCellSync<TData> | undefined, typed: boolean): ExportCell[][] {
  return plan.pivot ? plan.rows.map((viewRow) => pivotExportRow(state, columns, viewRow, text, typed)) : buildRowsAt(state, plan.rows, text, columns, formatCell, typed);
}

/**
 * Resolves the rows to export via the cell-type pipeline, in the requested `scope` order. With
 * `options.text: "display"` the cell type's display text (`toDisplayText ?? toText`) is used; the
 * default `'export'` uses `toText` (CSV/XLSX). Every scope emits all visible columns, so a
 * row-shaped export always matches its header row. Hole rows (unloaded indices of a lazy grid's
 * sparse `data`) are skipped in every scope. `options.maxRows` caps the number of rows built.
 */
export function buildExportRows(state: DataGridReadState, scope: ExportScope, options: BuildExportRowsOptions = {}): string[][] {
  const { text = "export" } = options;
  const plan = exportRowPlan(state, scope);
  const maxRows = options.maxRows === undefined ? undefined : normalizeLimit(options.maxRows, Number.POSITIVE_INFINITY);
  return buildPlanRows(state, maxRows === undefined ? plan : { ...plan, rows: plan.rows.slice(0, maxRows) }, text, state.visibleColumns, undefined, false) as string[][];
}

function buildRowsAt<TData>(
  state: DataGridReadState,
  dataIndices: readonly number[],
  text: "export" | "display",
  columns: readonly ExportColumn[] = state.visibleColumns,
  formatCell?: FormatExportCellSync<TData>,
  typed = false,
): ExportCell[][] {
  return dataIndices.map((dataRowIndex) => mapExportRow(state, columns, state.data[dataRowIndex] as TData, text, formatCell, typed));
}

/** {@link buildRowsAt} for a `formatCell` that may return promises: each slice of rows settles its promises before the next slice starts. */
async function buildRowsAtAsync<TData>(
  state: DataGridReadState,
  plan: ExportRowPlan,
  columns: readonly ExportColumn[],
  formatCell: FormatExportCell<TData> | undefined,
  typed: boolean,
  signal: AbortSignal,
  onSlice?: (rows: ExportCell[][]) => void,
): Promise<ExportCell[][]> {
  const rows: ExportCell[][] = [];
  for (let from = 0; from < plan.rows.length; from += SLICE_ROWS) {
    throwIfAborted(signal);
    const pending: PendingCell[] = [];
    const slice: ExportCell[][] = [];
    for (const ref of plan.rows.slice(from, from + SLICE_ROWS)) {
      slice.push(plan.pivot ? pivotExportRow(state, columns, ref, "export", typed) : mapExportRow(state, columns, state.data[ref] as TData, "export", formatCell, typed, signal, pending));
    }
    if (pending.length > 0) await settlePending(pending, typed, signal);
    if (onSlice) onSlice(slice);
    else for (const row of slice) rows.push(row);
  }
  return rows;
}

type ExportColumn = DataGridReadState["visibleColumns"][number];

/** The columns and the rows to build: at most `maxRows` rows, with a dev-only warning when the scope exceeds the cap. */
function cappedExportPlan(state: DataGridReadState, scope: ExportScope, rawMaxRows: number | undefined, columnIds: readonly string[] | undefined) {
  const maxRows = rawMaxRows === undefined ? undefined : normalizeLimit(rawMaxRows, Number.POSITIVE_INFINITY);
  const columns = resolveExportColumns(state, columnIds);
  const plan = exportRowPlan(state, scope);
  if (maxRows !== undefined && plan.rows.length > maxRows && isDev()) console.warn(`[data-grid-io] export truncated to ${maxRows} of ${plan.rows.length} rows (maxRows)`);
  return { columns, plan: maxRows === undefined ? plan : { ...plan, rows: plan.rows.slice(0, maxRows) } };
}

function buildCappedExportRows<TData>(state: DataGridReadState, scope: ExportScope, rawMaxRows: number | undefined, shape: ExportShapeOptions<TData, FormatExportCellSync<TData>>, typed: boolean): ExportCell[][] {
  const { columns, plan } = cappedExportPlan(state, scope, rawMaxRows, shape.columns);
  return buildPlanRows(state, plan, "export", columns, shape.formatCell, typed);
}

function buildCappedExportRowsAsync<TData>(state: DataGridReadState, scope: ExportScope, rawMaxRows: number | undefined, shape: ExportShapeOptions<TData>, typed: boolean, signal: AbortSignal, onSlice?: (rows: ExportCell[][]) => void): Promise<ExportCell[][]> {
  const { columns, plan } = cappedExportPlan(state, scope, rawMaxRows, shape.columns);
  return buildRowsAtAsync(state, plan, columns, shape.formatCell, typed, signal, onSlice);
}

/** Header row text for each exported column: the visible columns, or the columns named by `columnIds`. */
export function buildExportHeaders(state: DataGridReadState, columnIds?: readonly string[], overrides?: Readonly<Record<string, string>>): string[] {
  return resolveExportColumns(state, columnIds).map((column) => (overrides && Object.hasOwn(overrides, column.id) ? overrides[column.id]! : exportHeaderText(state, column)));
}

/** A generated column under a key's header group reads `key / value`, so the flat header row keeps the key. */
function exportHeaderText(state: DataGridReadState, column: ExportColumn): string {
  const model = isPivotColumn(column) ? state.pivot?.groupModel : undefined;
  const groupId = model?.paths.get(column.id)?.[0];
  const group = groupId === undefined ? undefined : model?.groups.get(groupId)?.def;
  return group ? `${columnLabelText(group)} / ${columnLabelText(column)}` : columnLabelText(column);
}

/** Triggers a browser download of `blob` named `fileName`, via a temporary anchor + object URL (revoke deferred — see below). */
export function downloadBlob(blob: Blob, fileName: string): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  anchor.style.display = "none";
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  // Firefox/Safari read the blob URL asynchronously after click(); revoking on the same tick can truncate the download.
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

/** Options for {@link buildXlsx}. */
export type BuildXlsxOptions<TData = unknown> = ExportShapeOptions<TData> & {
  /** Row scope, same semantics as {@link ExportGridOptions.scope}; default 'view'. */
  scope?: ExportScope;
  /** Whether to emit a header row; default true. */
  includeHeaders?: boolean;
  /** Name of the single sheet inside the workbook; default 'Sheet1'. An invalid Excel sheet name (empty, over 31 characters, `[]:*?/\`, a leading or trailing `'`, `history` in any case) rejects. */
  sheetName?: string;
  /** Same row cap as {@link ExportGridOptions.maxRows}. */
  maxRows?: number;
  /** Passed to `formatCell` as `ctx.signal`; an aborted signal rejects the build between slices of rows. */
  signal?: AbortSignal;
  /** Same as {@link ExportGridOptions.xlsxWriter}; default `"buffered"`. */
  xlsxWriter?: XlsxWriterMode;
};

const XLSX_TYPE = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

function xlsxBlob(bytes: Uint8Array): Blob {
  // hucre types its output as ArrayBufferLike, but its writers never return a SharedArrayBuffer view
  return new Blob([bytes as Uint8Array<ArrayBuffer>], { type: XLSX_TYPE });
}

/** Receives the rows of one sheet slice by slice and turns them into the file. */
type XlsxSink = { add(rows: readonly (readonly ExportCell[])[]): void; finish(): Promise<Blob> };

async function createXlsxSink(name: string, mode: XlsxWriterMode | undefined): Promise<XlsxSink> {
  if (mode === "stream") {
    const { XlsxStreamWriter } = await import("./xlsx-writer");
    // no rollover and no header repeat: the file holds the same single sheet as the buffered writer
    const writer = new XlsxStreamWriter({ name, maxRowsPerSheet: Number.POSITIVE_INFINITY, repeatHeaders: false });
    return {
      add: (rows) => {
        for (const row of rows) writer.addRow(row as ExportCell[]);
      },
      finish: async () => xlsxBlob(await writer.finish()),
    };
  }
  const table: (readonly ExportCell[])[] = [];
  return {
    add: (rows) => {
      for (const row of rows) table.push(row);
    },
    finish: async () => {
      const { writeXlsx } = await import("./xlsx-writer");
      return xlsxBlob(await writeXlsx({ sheets: [{ name, rows: table as ExportCell[][] }] }));
    },
  };
}

const cutRow = (row: readonly ExportCell[]): ExportCell[] => row.map((cell) => (typeof cell === "string" ? cutCell(cell) : cell));

/**
 * Builds an xlsx `Blob` from the grid's state without triggering a download — for server uploads
 * or inspecting the workbook before it leaves the browser. Values go through each column's cell
 * type `toText` like `exportGrid`. Built-in `number`, `date`, and `checkbox` columns land typed, other columns as
 * string cells, never formulas; `formatCell` overrides both. hucre loads lazily.
 */
export async function buildXlsx<TData = unknown>(state: DataGridReadState, options: BuildXlsxOptions<TData> = {}): Promise<Blob> {
  const { scope = "view", includeHeaders = true, sheetName = "Sheet1", maxRows, signal = NEVER_ABORTED } = options;
  const sink = await createXlsxSink(sheetName, options.xlsxWriter);
  if (includeHeaders) sink.add([cutRow(buildExportHeaders(state, options.columns, options.headers))]);
  await buildCappedExportRowsAsync(state, scope, maxRows, options, true, signal, (slice) => sink.add(slice.map(cutRow)));
  return sink.finish();
}

/**
 * Builds a CSV `Blob` from the rows the grid holds, without a download. Synchronous; cells go
 * through each column's cell type `toText` like `exportGrid`, then `formatCell`.
 */
export function buildCsv<TData = unknown>(state: DataGridReadState, options: BuildCsvOptions<TData> = {}): Blob {
  const rows = buildCappedExportRows(state, options.scope ?? "view", options.maxRows, options, false) as string[][];
  return csvBlob(state, rows, options);
}

function csvBlob(state: DataGridReadState, rows: string[][], options: Pick<BuildCsvOptions, "includeHeaders" | "csvDelimiter" | "csvBom" | "sanitizeFormulas" | "columns" | "headers">): Blob {
  const { includeHeaders = true, csvDelimiter = ",", csvBom = true, sanitizeFormulas = true } = options;
  const table = includeHeaders ? [buildExportHeaders(state, options.columns, options.headers), ...rows] : rows;
  return new Blob([(csvBom ? BOM : "") + rowsToCsv(table, { delimiter: csvDelimiter, sanitizeFormulas })], { type: "text/csv;charset=utf-8;" });
}

async function buildCsvAsync<TData>(state: DataGridReadState, options: ExportGridOptions<TData>, signal: AbortSignal): Promise<Blob> {
  const rows = (await buildCappedExportRowsAsync(state, options.scope ?? "view", options.maxRows, options, false, signal)) as string[][];
  return csvBlob(state, rows, options);
}

function isValidSheetName(name: string): boolean {
  return name.length > 0 && name.length <= 31 && !INVALID_SHEET_NAME.test(name) && !name.startsWith("'") && !name.endsWith("'") && name.toLowerCase() !== "history";
}

function cutCell(text: string): string {
  return text.length > MAX_CELL_TEXT ? text.slice(0, MAX_CELL_TEXT) : text;
}

function throwIfAborted(signal: AbortSignal | undefined): void {
  if (signal?.aborted) throw signal.reason ?? new DOMException("The export was aborted.", "AbortError");
}

function loadedResult(state: DataGridReadState, scope: ExportScope, maxRows: number | undefined): ExportResult {
  const total = exportRowPlan(state, scope).rows.length;
  return { rowCount: maxRows === undefined ? total : Math.min(total, maxRows), truncated: maxRows !== undefined && total > maxRows };
}

type ExportDelivery = { fileName: string; output: ExportOutput | undefined; signal: AbortSignal };

async function deliver(blob: Blob, format: "csv" | "xlsx", { fileName, output, signal }: ExportDelivery): Promise<void> {
  throwIfAborted(signal);
  const file = `${fileName}.${format}`;
  if (output) await output(blob, { fileName: file, format, signal });
  else downloadBlob(blob, file);
}

/** Exports the rows `source` returns; CSV is written batch by batch, XLSX goes through the chosen `xlsxWriter`. */
async function exportFromSource<TData>(state: DataGridReadState, source: ExportSource, options: ExportGridOptions<TData>, delivery: ExportDelivery): Promise<ExportResult> {
  const { format = "csv", includeHeaders = true, csvDelimiter = ",", csvBom = true, sanitizeFormulas = true, sheetName = "Sheet1", onProgress } = options;
  const xlsx = format === "xlsx";
  if (xlsx && !isValidSheetName(sheetName)) throw new Error(`[data-grid-io] invalid xlsx sheet name: ${sheetName}`);
  const headers = buildExportHeaders(state, options.columns, options.headers).map(cutCell);
  const requested = normalizeLimit(options.maxRows, DEFAULT_SOURCE_MAX_ROWS);
  const maxRows = xlsx ? Math.min(requested, XLSX_MAX_ROWS - (includeHeaders ? 1 : 0), Math.floor(XLSX_MAX_CELLS / Math.max(headers.length, 1))) : requested;
  const run: ExportRowsOptions<TData> = {
    source,
    columns: options.columns,
    formatCell: options.formatCell,
    typed: xlsx,
    maxRows,
    maxBytes: normalizeLimit(options.maxBytes, DEFAULT_SOURCE_MAX_BYTES),
    signal: delivery.signal,
    onProgress,
  };

  if (!xlsx) {
    const parts: Blob[] = [new Blob([csvBom ? BOM : ""])];
    let started = false;
    const append = (rows: readonly (readonly string[])[]): number => {
      if (rows.length === 0) return 0;
      const text = (started ? CSV_EOL : "") + rowsToCsv(rows, { delimiter: csvDelimiter, sanitizeFormulas });
      started = true;
      const part = new Blob([text]);
      parts.push(part);
      return part.size;
    };
    if (includeHeaders) append([headers]);
    const result = await exportRows<TData, string>(state, run, append);
    await deliver(new Blob(parts, { type: "text/csv;charset=utf-8;" }), "csv", delivery);
    return result;
  }

  const sink = await createXlsxSink(sheetName, options.xlsxWriter);
  if (includeHeaders) sink.add([headers]);
  const result = await exportRows<TData, ExportCell>(state, run, (rows) => {
    let size = 0;
    const cuts = rows.map(cutRow);
    for (const cut of cuts) for (const cell of cut) size += exportCellSize(cell);
    sink.add(cuts);
    return size;
  });
  await deliver(await sink.finish(), "xlsx", delivery);
  return result;
}

/**
 * Serializes the grid to CSV or XLSX and triggers a download, or hands the file to `output`.
 * Values go through each column's cell type `toText` (never raw values) unless `formatCell`
 * replaces them. hucre is loaded lazily (dynamic `import()`) so the dependency never loads for
 * CSV-only consumers.
 */
export async function exportGrid<TData = unknown>(state: DataGridReadState, options: ExportGridOptions<TData> = {}): Promise<ExportResult> {
  const controller = new AbortController();
  const signal = options.signal ? AbortSignal.any([options.signal, controller.signal]) : controller.signal;
  try {
    return await runExport(state, options, signal);
  } catch (error) {
    controller.abort(error);
    throw error;
  }
}

async function runExport<TData>(state: DataGridReadState, options: ExportGridOptions<TData>, signal: AbortSignal): Promise<ExportResult> {
  const { source, output, format = "csv", scope = "view", fileName = "export" } = options;
  const delivery: ExportDelivery = { fileName, output, signal };
  if (source) return exportFromSource(state, source, options, delivery);
  const maxRows = options.maxRows === undefined ? undefined : normalizeLimit(options.maxRows, Number.POSITIVE_INFINITY);
  if (format === "csv") {
    await deliver(await buildCsvAsync(state, { ...options, maxRows }, signal), "csv", delivery);
    return loadedResult(state, scope, maxRows);
  }

  await deliver(await buildXlsx(state, { ...options, maxRows, signal }), "xlsx", delivery);
  return loadedResult(state, scope, maxRows);
}

/** Clamps a caller limit to a non-negative integer: `NaN` falls back, `Infinity` becomes the largest safe integer. */
export function normalizeLimit(value: number | undefined, fallback: number): number {
  if (value === undefined || Number.isNaN(value)) return fallback;
  return Math.min(Math.max(0, Math.floor(value)), Number.MAX_SAFE_INTEGER);
}

import { getCellValue, type AnyColumnDef, type ServerSpec } from "@/registry/default/components/data-grid/data-grid";
import { serverSpecOf } from "@/registry/default/components/data-grid/data-grid-sdk";
import { normalizeLimit } from "./normalize-limit";
import { displayText, isDev, isThenable, type DataGridReadState } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Longest cell text an Excel worksheet holds; XLSX export and print cut longer text to it, CSV only a `formatCell` string. */
export const MAX_CELL_TEXT = 32_767;

/** What a `formatCell` hook returns. `null` and `undefined` make an empty cell. */
export type ExportCellValue = string | number | boolean | Date | null | undefined;

/** What `formatCell` receives for one exported cell. */
export type ExportCellContext<TData = unknown> = {
  /** The raw cell value. */
  value: unknown;
  /** The text the column's cell type exports by default. */
  text: string;
  row: TData;
  column: AnyColumnDef;
  /** Aborts when the export is cancelled, fails, or stops at a limit. Pass it to a request. */
  signal: AbortSignal;
};

/** Replaces the exported value of every cell. Runs once per cell, after the cell type made its text. */
export type FormatExportCellSync<TData = unknown> = (ctx: ExportCellContext<TData>) => ExportCellValue;

/** {@link FormatExportCellSync}, or a hook that returns a promise. The promises of one slice of rows settle together. */
export type FormatExportCell<TData = unknown> = (ctx: ExportCellContext<TData>) => ExportCellValue | PromiseLike<ExportCellValue>;

/** The signal of an export that cannot be cancelled. */
export const NEVER_ABORTED: AbortSignal = new AbortController().signal;

/** One exported cell after the format step: CSV rows hold strings only, XLSX rows keep typed values. */
export type ExportCell = string | number | boolean | Date | null;

/** What an {@link ExportSource} receives. */
export type ExportSourceContext = {
  /** The grid's sort, filters, and search text when the export started. Send it to your server. */
  spec: ServerSpec;
  /** Aborts when the export is cancelled or stops at a limit. Pass it to your request. */
  signal: AbortSignal;
  /** The ids of the columns the export writes, in order. Narrow your query to them. */
  columnIds: readonly string[];
};

/** Rows of the whole result for an "all rows" export. Return one array, or an async iterable of batches (an async generator that pages through your API). */
export type ExportSource<TData = unknown> = (ctx: ExportSourceContext) => readonly TData[] | Promise<readonly TData[]> | AsyncIterable<readonly TData[]>;

export const SLICE_ROWS = 1000;
/** Most `formatCell` promises awaited together. */
const ASYNC_GROUP_CELLS = 10_000;
const MAX_EMPTY_BATCHES = 1000;
const YIELD_AFTER_MS = 40;

export const DEFAULT_SOURCE_MAX_ROWS = 1_000_000;
export const DEFAULT_SOURCE_MAX_BYTES = 256 * 1024 * 1024;

/** Running totals after a batch: data rows written and file bytes (xlsx: characters) so far. */
export type ExportProgress = { rowCount: number; byteCount: number };

/** What a finished export wrote. */
export type ExportResult = {
  rowCount: number;
  /** True when `maxRows` or `maxBytes` ended the export before the source did. */
  truncated: boolean;
};

/** Resolved limits and callbacks of one source export. */
export type ExportRowsOptions<TData = unknown> = {
  source: ExportSource;
  /** Column ids to write, in order; default the visible columns. An unknown id throws before the source runs. */
  columns?: readonly string[];
  formatCell?: FormatExportCell<TData>;
  /** Cell text source: `"export"` uses the cell type's `toText` (default), `"display"` its display text (print). */
  text?: "export" | "display";
  /** Keep numbers, booleans and Dates typed (XLSX). Default: every cell becomes a string (CSV). */
  typed?: boolean;
  /** Most data rows to write. Default `1_000_000`; a negative or fractional value rounds to a non-negative integer. */
  maxRows?: number;
  /** Most bytes to write (xlsx: characters). Default 256 MiB. */
  maxBytes?: number;
  signal?: AbortSignal;
  onProgress?: (progress: ExportProgress) => void;
};

function isAsyncIterable(value: unknown): value is AsyncIterable<readonly unknown[]> {
  return typeof value === "object" && value !== null && Symbol.asyncIterator in value;
}

/** A message-channel hop: unlike `setTimeout`, a hidden tab does not throttle it. */
function yieldToEventLoop(): Promise<void> {
  if (typeof MessageChannel === "undefined") return new Promise((resolve) => setTimeout(resolve, 0));
  return new Promise((resolve) => {
    const { port1, port2 } = new MessageChannel();
    port1.onmessage = () => {
      port1.close();
      resolve();
    };
    port2.postMessage(0);
  });
}

export function abortReason(signal: AbortSignal): unknown {
  return signal.reason ?? new DOMException("The export was aborted.", "AbortError");
}

/**
 * Reads the batches of `source`, maps each row through the cell types, and hands the text rows to
 * `onBatch` (which returns the byte size it kept). Stops at `maxRows` or `maxBytes` and aborts the source.
 */
export async function exportRows<TData = unknown, TCell extends ExportCell = string>(
  state: DataGridReadState,
  options: ExportRowsOptions<TData>,
  onBatch: (rows: TCell[][]) => number,
): Promise<ExportResult> {
  const { source, signal: outer, onProgress, formatCell, typed = false } = options;
  const maxRows = normalizeLimit(options.maxRows, DEFAULT_SOURCE_MAX_ROWS);
  const maxBytes = normalizeLimit(options.maxBytes, DEFAULT_SOURCE_MAX_BYTES);
  const columns = resolveExportColumns(state, options.columns);
  const columnIds = columns.map((column) => column.id);
  const inner = new AbortController();
  const stop = () => inner.abort(outer?.reason);
  if (outer?.aborted) throw abortReason(outer);
  outer?.addEventListener("abort", stop, { once: true });

  const spec: ServerSpec = serverSpecOf(state);
  let rowCount = 0;
  let byteCount = 0;
  let truncated = false;
  // The slice that crosses maxBytes is written whole; the export is truncated only if more rows follow it.
  let overBytes = false;
  let skippedRows = 0;
  let emptyBatches = 0;
  const maxSkippedRows = Math.max(maxRows, 1) * 2;
  let iterator: AsyncIterator<readonly unknown[]> | undefined;

  const untilAborted = <T,>(promise: Promise<T>): Promise<T> => {
    if (!outer) return promise;
    return new Promise<T>((resolve, reject) => {
      const fail = () => reject(abortReason(outer));
      if (outer.aborted) return fail();
      outer.addEventListener("abort", fail, { once: true });
      const settle = (done: () => void) => () => {
        outer.removeEventListener("abort", fail);
        done();
      };
      promise.then(
        (value) => settle(() => resolve(value))(),
        (error) => settle(() => reject(error))(),
      );
    });
  };

  let warnedBatchBytes = false;
  let sliceStarted = performance.now();
  const take = async (batch: unknown): Promise<void> => {
    if (!Array.isArray(batch)) throw new TypeError("[data-grid-io] an export source batch must be an array");
    emptyBatches = batch.length === 0 ? emptyBatches + 1 : 0;
    if (emptyBatches > MAX_EMPTY_BATCHES) throw new RangeError("[data-grid-io] an export source returned only empty batches");
    for (let from = 0; from < batch.length && !truncated; from += SLICE_ROWS) {
      const slice = batch.slice(from, from + SLICE_ROWS);
      const present = slice.filter((row) => row !== undefined && row !== null);
      if (overBytes && present.length > 0) {
        truncated = true;
        break;
      }
      skippedRows += slice.length - present.length;
      const room = maxRows - rowCount;
      if (present.length > room) truncated = true;
      else if (skippedRows > maxSkippedRows) throw new RangeError("[data-grid-io] an export source returned too many empty rows");
      const pending: PendingCell[] = [];
      const rows = present.slice(0, room).map((row) => mapExportRow(state, columns, row as TData, options.text ?? "export", formatCell, typed, inner.signal, pending) as TCell[]);
      if (pending.length > 0) await settlePending(pending, typed, inner.signal);
      rowCount += rows.length;
      const batchBytes = onBatch(rows);
      if (Number.isFinite(batchBytes)) byteCount += batchBytes;
      else if (!warnedBatchBytes && isDev()) {
        warnedBatchBytes = true;
        console.warn("[data-grid-io] onBatch must return the byte size it kept as a finite number; this batch counts as 0 bytes");
      }
      if (byteCount > maxBytes) overBytes = true;
      if (performance.now() - sliceStarted > YIELD_AFTER_MS) {
        await yieldToEventLoop();
        if (outer?.aborted) throw abortReason(outer);
        sliceStarted = performance.now();
      }
    }
    try {
      onProgress?.({ rowCount, byteCount });
    } catch (error) {
      if (isDev()) console.warn("[data-grid-io] onProgress threw", error);
    }
  };

  try {
    const result = source({ spec, signal: inner.signal, columnIds });
    if (isAsyncIterable(result)) {
      iterator = result[Symbol.asyncIterator]();
      while (!truncated) {
        const step = await untilAborted(iterator.next());
        if (outer?.aborted) throw abortReason(outer);
        if (step.done) break;
        await take(step.value);
      }
    } else {
      const batch = await untilAborted(Promise.resolve(result));
      if (outer?.aborted) throw abortReason(outer);
      await take(batch);
    }
  } finally {
    outer?.removeEventListener("abort", stop);
    inner.abort();
    void Promise.resolve(iterator?.return?.()).catch(() => {});
  }

  if (truncated && isDev()) console.warn(`[data-grid-io] export stopped at ${rowCount} rows (maxRows ${maxRows}, maxBytes ${maxBytes})`);
  return { rowCount, truncated };
}

/** Resolves column ids against all grid columns, hidden ones included; no ids means the visible columns. */
export function resolveExportColumns(state: DataGridReadState, ids: readonly string[] | undefined): readonly AnyColumnDef[] {
  if (ids === undefined) return state.visibleColumns;
  const all = state.pivot ? [...(state.columns ?? []), ...state.pivot.columns] : (state.columns ?? state.visibleColumns);
  const byId = new Map(all.map((column) => [column.id, column] as const));
  return ids.map((id) => {
    const column = byId.get(id);
    if (!column) throw new RangeError(`[data-grid-io] unknown export column: ${id}`);
    return column;
  });
}

function cutText(text: string): string {
  return text.length > MAX_CELL_TEXT ? text.slice(0, MAX_CELL_TEXT) : text;
}

function toCsvCell(value: ExportCellValue): string {
  if (typeof value === "string") return cutText(value);
  if (typeof value === "number") return Number.isFinite(value) ? String(value) : "";
  if (typeof value === "boolean") return String(value);
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? "" : value.toISOString();
  return "";
}

function toTypedCell(value: ExportCellValue): ExportCell {
  if (typeof value === "string") return cutText(value);
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value === "boolean") return value;
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
  return null;
}

const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** The typed XLSX cell of a built-in `number`, `date`, or `checkbox` column; any other column keeps its text. */
function builtInTypedCell(type: string | undefined, value: unknown, text: string): ExportCell {
  if (type === "number") {
    const number = text === "" ? Number.NaN : Number(text);
    return Number.isFinite(number) ? number : text;
  }
  if (type === "checkbox") return typeof value === "boolean" ? value : text;
  if (type === "date") {
    const match = typeof value === "string" ? ISO_DATE.exec(value) : null;
    if (!match) return text;
    const date = new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])));
    return date.getUTCMonth() === Number(match[2]) - 1 ? date : text;
  }
  return text;
}

/** Characters one exported cell adds to the file; typed cells count as `String(value)`. */
export function exportCellSize(cell: ExportCell): number {
  if (cell === null) return 0;
  if (typeof cell === "string") return cell.length;
  return cell instanceof Date ? cell.toISOString().length : String(cell).length;
}

/** A cell whose `formatCell` returned a promise: the value lands in `row[index]` once it settles. */
export type PendingCell = { row: ExportCell[]; index: number; value: PromiseLike<ExportCellValue> };

/** Awaits the promises together in groups, converts each value like a sync one, and reads `signal` after every group. */
export async function settlePending(pending: readonly PendingCell[], typed: boolean, signal: AbortSignal): Promise<void> {
  // a later group's rejection must not surface as an unhandled rejection while an earlier group is awaited
  for (const cell of pending) Promise.resolve(cell.value).catch(() => {});
  for (let from = 0; from < pending.length; from += ASYNC_GROUP_CELLS) {
    const group = pending.slice(from, from + ASYNC_GROUP_CELLS);
    const values = await Promise.all(group.map((cell) => cell.value));
    if (signal.aborted) throw abortReason(signal);
    group.forEach((cell, i) => {
      cell.row[cell.index] = typed ? toTypedCell(values[i]) : toCsvCell(values[i]);
    });
  }
}

/**
 * Maps one row through the cell types, then `formatCell`; the loaded rows and the source rows share it.
 * A promise from `formatCell` goes to `pending` and leaves the cell empty until `settlePending`; without `pending` it throws.
 */
export function mapExportRow<TData>(
  state: DataGridReadState,
  columns: readonly AnyColumnDef[],
  row: TData,
  text: "export" | "display",
  formatCell: FormatExportCell<TData> | undefined,
  typed: boolean,
  signal: AbortSignal = NEVER_ABORTED,
  pending?: PendingCell[],
): ExportCell[] {
  const cells = new Array<ExportCell>(columns.length);
  for (let index = 0; index < columns.length; index++) {
    const column = columns[index]!;
    const cellType = state.cellTypes[column.type ?? "text"];
    const value = getCellValue<unknown, AnyColumnDef>(row, column);
    const cellText = cellType ? (text === "display" ? displayText(cellType, value, column.options) : cellType.toText(value, column.options)) : "";
    if (!formatCell) {
      cells[index] = typed ? builtInTypedCell(column.type, value, cellText) : cellText;
      continue;
    }
    const formatted = formatCell({ value, text: cellText, row, column, signal });
    if (isThenable<ExportCellValue>(formatted)) {
      if (!pending) throw new TypeError("[data-grid-io] formatCell returned a promise; use exportGrid or buildXlsx, which await it");
      pending.push({ row: cells, index, value: formatted });
      cells[index] = null;
      continue;
    }
    cells[index] = typed ? toTypedCell(formatted) : toCsvCell(formatted);
  }
  return cells;
}

"use client";

import { useCallback } from "react";
import { useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import { exportGrid, type ExportGridOptions, type ExportResult } from "./export-grid";

/** Public export trigger returned by {@link useDataGridExport}. */
export type UseDataGridExportResult = {
  /** Serializes the grid per `options` and triggers a browser download, or hands the file to `options.output`. */
  exportGrid: <TData = unknown>(options?: ExportGridOptions<TData>) => Promise<ExportResult>;
};

/** Wires {@link exportGrid} to the grid's store instance, for toolbar buttons and custom triggers. */
export function useDataGridExport(): UseDataGridExportResult {
  const storeApi = useDataGridStoreApi();

  const run = useCallback(
    <TData = unknown,>(options?: ExportGridOptions<TData>) => exportGrid(storeApi.getState(), options),
    [storeApi],
  );

  return { exportGrid: run };
}

"use client";

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import { Download } from "lucide-react";
import { useDataGridLabels } from "@/registry/default/components/data-grid/data-grid";
import { isDev } from "@/registry/default/components/data-grid/data-grid-sdk";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useDataGridExport } from "./use-data-grid-export";
import type { ExportGridOptions, ExportResult } from "./export-grid";

type ExportFormat = "xlsx" | "csv";

/** Props for {@link DataGridExportButton}. */
export type DataGridExportButtonProps<TData = unknown> = {
  className?: string;
  /** The formats the button offers; one format exports on click, several open a menu. Default `["xlsx", "csv"]`. */
  formats?: readonly ExportFormat[];
  /** Export options applied to both formats besides `format` itself, including `columns`, `formatCell`, and `output`; default `{ scope: 'view', includeHeaders: true }`. With `source`, the menu adds "all rows" items that export the source's rows; the plain items export the rows the grid holds. */
  options?: Omit<ExportGridOptions<TData>, "format">;
  /** Receives the rejection when an export fails; without it, the failure logs a dev-only warning. */
  onError?: (error: unknown, format: ExportFormat) => void;
};

/**
 * Toolbar-slot export trigger: a ghost icon button opening a dropdown of xlsx/csv, wired to
 * {@link useDataGridExport}. `size-8` + ghost variant matches the toolbar's other icon buttons.
 */
export function DataGridExportButton<TData = unknown>(props: DataGridExportButtonProps<TData>): ReactNode {
  const { className, formats = ["xlsx", "csv"], options, onError } = props;
  const labels = useDataGridLabels();
  const { exportGrid } = useDataGridExport();
  const { source, ...loadedOptions } = options ?? {};
  const [running, setRunning] = useState(false);
  const [done, setDone] = useState("");
  const controllerRef = useRef<AbortController | null>(null);

  useEffect(() => () => controllerRef.current?.abort(), []);

  const cancelExport = useCallback(() => controllerRef.current?.abort(), []);

  const runExport = (format: ExportFormat, all: boolean) => {
    const controller = new AbortController();
    controllerRef.current = controller;
    const tracked = all || loadedOptions.output !== undefined;
    setDone("");
    setRunning(tracked);
    const signal = loadedOptions.signal ? AbortSignal.any([controller.signal, loadedOptions.signal]) : controller.signal;
    exportGrid({ ...loadedOptions, format, signal, ...(all ? { source } : {}) })
      .then((result: ExportResult) => {
        if (tracked && controllerRef.current === controller) setDone(labels.io.exportDone(result.rowCount, result.truncated));
      })
      .catch((error: unknown) => {
        const current = controllerRef.current === controller;
        if (signal.aborted) {
          if (tracked && current) setDone(labels.io.exportCancelled);
          return;
        }
        if (tracked && current) setDone(labels.io.exportFailed);
        if (onError) {
          onError(error, format);
          return;
        }
        if (isDev()) console.warn(`[data-grid-io] ${format} export failed`, error);
      })
      .finally(() => {
        if (controllerRef.current === controller) setRunning(false);
      });
  };

  const singleFormat = formats.length === 1 && !source;
  const trigger = (
    <Button type="button" variant="ghost" size="icon" className={className} aria-label={labels.io.exportButtonAriaLabel} aria-busy={running || undefined} onClick={singleFormat ? () => (running ? cancelExport() : runExport(formats[0]!, false)) : undefined}>
      <Download />
    </Button>
  );

  const status = (
    <span role="status" className="sr-only">
      {done}
    </span>
  );

  if (singleFormat) {
    return (
      <>
        {trigger}
        {status}
      </>
    );
  }

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger render={trigger} />
        <DropdownMenuContent align="start">
          {formats.includes("xlsx") && (
            <DropdownMenuItem disabled={running} onClick={() => runExport("xlsx", false)}>
              {labels.io.exportXlsx}
            </DropdownMenuItem>
          )}
          {formats.includes("csv") && (
            <DropdownMenuItem disabled={running} onClick={() => runExport("csv", false)}>
              {labels.io.exportCsv}
            </DropdownMenuItem>
          )}
          {source && formats.includes("xlsx") && (
            <DropdownMenuItem disabled={running} onClick={() => runExport("xlsx", true)}>
              {labels.io.exportAllXlsx}
            </DropdownMenuItem>
          )}
          {source && formats.includes("csv") && (
            <DropdownMenuItem disabled={running} onClick={() => runExport("csv", true)}>
              {labels.io.exportAllCsv}
            </DropdownMenuItem>
          )}
          {running && <DropdownMenuItem onClick={cancelExport}>{labels.io.exportCancel}</DropdownMenuItem>}
        </DropdownMenuContent>
      </DropdownMenu>
      {status}
    </>
  );
}

import { type DataGridReadState, type GridDirection } from "@/registry/default/components/data-grid/data-grid-sdk";
import { normalizeLimit } from "./normalize-limit";
import { MAX_CELL_TEXT, buildExportHeaders, buildExportRows, exportRowPlan, exportRows } from "./export-grid";
import { abortReason, type ExportSource } from "./export-source";

/** Default number of rows printed when `maxRows` is not given. */
const DEFAULT_PRINT_MAX_ROWS = 10_000;
/** Hard ceiling on the printed table's cell count (a multi-million-cell DOM table hangs the print dialog). */
const PRINT_CELL_CEILING = 500_000;
/** Longest `css` option, in characters. */
export const MAX_PRINT_CSS_LENGTH = 65_536;
/** Fallback removal (ms) for the print iframe when the window's `afterprint` never fires. */
const PRINT_FALLBACK_MS = 60_000;

/** Paper sizes for {@link PrintGridOptions.paperSize}. */
export type PrintPaperSize = "A3" | "A4" | "Letter" | "Legal";

/** CSS `@page` size keyword per paper size. */
const PAPER_SIZE_CSS: Record<PrintPaperSize, string> = { A3: "A3", A4: "A4", Letter: "letter", Legal: "legal" };

/** Options for {@link printGrid}. */
export type PrintGridOptions = {
  /** Which rows to print: `"view"` (default) prints the current sort and filter order, every page of a paged grid; `"page"` the shown page only; `"all"` every row in `data` order; `"selection"` the selected rows in view order. */
  scope?: "view" | "page" | "all" | "selection";
  /** Printed as an `<h1>` heading and the document title. */
  title?: string;
  /** Emit a `<thead>` header row; default `true`. */
  includeHeaders?: boolean;
  /** Paper size of the printed page; default `"A4"`. */
  paperSize?: PrintPaperSize;
  /** Page orientation; default: `landscape` above 6 visible columns, else `portrait`. */
  orientation?: "portrait" | "landscape";
  /** Cap on the rows printed (the header row is not counted); default 10,000, further cut by the 500,000-cell ceiling. */
  maxRows?: number;
  /** Reading direction of the printed page. Default: the direction of the page that calls print. */
  direction?: GridDirection;
  /** Where the rows come from, for a grid that holds one page or some loaded blocks. With `source` the print ignores `scope` and the held rows. It receives the same context as the export source, and the `maxRows` and cell bounds apply. */
  source?: ExportSource;
  /** Header text per column id, replacing the column's label. A column without an entry keeps its label. */
  headers?: Readonly<Record<string, string>>;
  /** Extra CSS appended after the built-in rules, in a second `<style>` node. Longer than 65,536 characters rejects with a `RangeError`. Build it from constants only: a cell value in `css` can load a remote URL. */
  css?: string;
  /** Cancels the print: the promise rejects with the signal's reason and no dialog opens. */
  signal?: AbortSignal;
};

/** What a finished {@link printGrid} printed. */
export type PrintGridResult = {
  rowCount: number;
  /** True when `maxRows` or the cell ceiling cut the output. */
  truncated: boolean;
};

let openIframe: HTMLIFrameElement | null = null;
let activeRun: AbortController | null = null;
let fallbackTimer: ReturnType<typeof setTimeout> | null = null;

/** Removes the currently open print iframe and clears its fallback timer. */
function removeOpenIframe(): void {
  if (fallbackTimer !== null) {
    clearTimeout(fallbackTimer);
    fallbackTimer = null;
  }
  openIframe?.remove();
  openIframe = null;
}

function cutText(text: string): string {
  return text.length > MAX_CELL_TEXT ? text.slice(0, MAX_CELL_TEXT) : text;
}

function printCss(paperSize: string, orientation: "portrait" | "landscape"): string {
  return [
    `@page { size: ${paperSize} ${orientation}; margin: 12mm; }`,
    "body { font: 10pt/1.4 system-ui, sans-serif; color: #000; }",
    "h1 { font-size: 14pt; margin: 0 0 8px; }",
    "table { border-collapse: collapse; width: 100%; }",
    "thead { display: table-header-group; }",
    "tr { break-inside: avoid; }",
    "th, td { border: 1px solid #999; padding: 2px 6px; text-align: start; }",
    "th { font-weight: 600; }",
    "p { margin: 8px 0 0; }",
  ].join("\n");
}

type PrintRows = { rows: string[][]; note: string | undefined };

function loadedPrintRows(state: DataGridReadState, scope: NonNullable<PrintGridOptions["scope"]>, maxRows: number): PrintRows {
  const total = exportRowPlan(state, scope).rows.length;
  const rows = buildExportRows(state, scope, { text: "display", maxRows });
  return { rows, note: rows.length < total ? state.labels.io.printTruncated(rows.length, total) : undefined };
}

async function sourcePrintRows(state: DataGridReadState, source: ExportSource, maxRows: number, signal: AbortSignal): Promise<PrintRows> {
  const rows: string[][] = [];
  const result = await exportRows<unknown, string>(state, { source, text: "display", maxRows, signal }, (batch) => {
    let size = 0;
    for (const row of batch) {
      rows.push(row);
      for (const cell of row) size += cell.length;
    }
    return size;
  });
  if (signal.aborted) throw abortReason(signal);
  return { rows, note: result.truncated ? state.labels.io.printTruncatedSource(rows.length) : undefined };
}

/**
 * Prints the grid's rows as a plain paged table: the rows are resolved through the cell-type
 * pipeline's display text (`toDisplayText ?? toText`), built into a hidden, sandboxed iframe's
 * document with `textContent` only (no value ever passes an HTML parser), and the browser print
 * dialog is opened — its "Save as PDF" produces the PDF. Visible columns only, in view order;
 * lazy holes and hidden columns never print. `options.maxRows` caps the rows (default 10,000,
 * further cut to fit the 500,000-cell ceiling); when the cap cut the output, the table ends
 * with a truncation note. The iframe is removed on `afterprint` (with a 60 s fallback timer),
 * and a second call replaces the first, aborting its pending `source`. Without `source` the
 * dialog opens before the call returns. No-op without a DOM (SSR).
 */
export async function printGrid(state: DataGridReadState, options: PrintGridOptions = {}): Promise<PrintGridResult> {
  if (typeof document === "undefined") return { rowCount: 0, truncated: false };
  if (options.css !== undefined && options.css.length > MAX_PRINT_CSS_LENGTH) throw new RangeError(`[data-grid-io] print css is longer than ${MAX_PRINT_CSS_LENGTH} characters`);
  removeOpenIframe();
  activeRun?.abort();
  const run = new AbortController();
  activeRun = run;
  const signal = options.signal ? AbortSignal.any([options.signal, run.signal]) : run.signal;
  try {
    const colCount = state.visibleColumns.length;
    const maxRows = Math.min(normalizeLimit(options.maxRows, DEFAULT_PRINT_MAX_ROWS), Math.floor(PRINT_CELL_CEILING / Math.max(colCount, 1)));
    const { rows, note } = options.source ? await sourcePrintRows(state, options.source, maxRows, signal) : loadedPrintRows(state, options.scope ?? "view", maxRows);
    openPrintDocument(state, options, rows, note);
    return { rowCount: rows.length, truncated: note !== undefined };
  } finally {
    if (activeRun === run) activeRun = null;
  }
}

function openPrintDocument(state: DataGridReadState, options: PrintGridOptions, rows: string[][], note: string | undefined): void {
  const includeHeaders = options.includeHeaders ?? true;
  const colCount = state.visibleColumns.length;
  const headers = buildExportHeaders(state, undefined, options.headers);
  const orientation = options.orientation ?? (colCount > 6 ? "landscape" : "portrait");
  // Untyped callers can pass any string; only the fixed map reaches the CSS.
  const requestedSize = options.paperSize ?? "A4";
  const paperSize = Object.hasOwn(PAPER_SIZE_CSS, requestedSize) ? PAPER_SIZE_CSS[requestedSize] : "A4";

  const iframe = document.createElement("iframe");
  // attribute, not the sandbox IDL property: jsdom reflects the IDL property incompletely
  iframe.setAttribute("sandbox", "allow-same-origin allow-modals");
  // zero-size and off-screen: the iframe exists only to host the print document
  iframe.style.position = "fixed";
  iframe.style.width = "0";
  iframe.style.height = "0";
  iframe.style.border = "0";
  iframe.style.visibility = "hidden";
  document.body.append(iframe);

  const doc = iframe.contentDocument;
  const win = iframe.contentWindow;
  if (!doc || !win) {
    iframe.remove();
    return;
  }

  doc.documentElement.dir = options.direction ?? (getComputedStyle(document.documentElement).direction === "rtl" ? "rtl" : "ltr");
  doc.title = options.title ?? "";
  const meta = doc.createElement("meta");
  meta.httpEquiv = "Content-Security-Policy";
  meta.content = "default-src 'none'; style-src 'unsafe-inline'";
  const style = doc.createElement("style");
  style.textContent = printCss(paperSize, orientation);
  doc.head.append(meta, style);
  if (options.css) {
    const extra = doc.createElement("style");
    extra.textContent = options.css;
    doc.head.append(extra);
  }
  if (options.title) {
    const heading = doc.createElement("h1");
    heading.textContent = options.title;
    doc.body.append(heading);
  }

  const table = doc.createElement("table");
  if (includeHeaders) {
    const thead = doc.createElement("thead");
    const headerRow = doc.createElement("tr");
    for (const header of headers) {
      const th = doc.createElement("th");
      th.scope = "col";
      th.textContent = cutText(header);
      headerRow.append(th);
    }
    thead.append(headerRow);
    table.append(thead);
  }
  const tbody = doc.createElement("tbody");
  for (const row of rows) {
    const tr = doc.createElement("tr");
    for (let i = 0; i < row.length; i++) {
      const td = doc.createElement("td");
      const align = state.cellTypes[state.visibleColumns[i]!.type ?? "text"]?.align;
      if (align) td.style.textAlign = align;
      td.textContent = cutText(row[i]!);
      tr.append(td);
    }
    tbody.append(tr);
  }
  table.append(tbody);
  doc.body.append(table);
  if (note !== undefined) {
    const noteElement = doc.createElement("p");
    noteElement.textContent = note;
    doc.body.append(noteElement);
  }

  const cleanup = () => {
    win.removeEventListener("afterprint", cleanup);
    removeOpenIframe();
  };
  win.addEventListener("afterprint", cleanup);
  fallbackTimer = setTimeout(cleanup, PRINT_FALLBACK_MS);
  openIframe = iframe;
  win.print();
}

"use client";

import { useCallback } from "react";
import { useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import { printGrid, type PrintGridOptions, type PrintGridResult } from "./print-grid";

/** Public print trigger returned by {@link useDataGridPrint}. */
export type UseDataGridPrintResult = {
  /** Prints the grid's rows as a paged table and opens the browser print dialog. */
  printGrid: (options?: PrintGridOptions) => Promise<PrintGridResult>;
};

/** Wires {@link printGrid} to the grid's store instance, for toolbar buttons and custom triggers. */
export function useDataGridPrint(): UseDataGridPrintResult {
  const storeApi = useDataGridStoreApi();

  const run = useCallback(
    (options?: PrintGridOptions) => printGrid(storeApi.getState(), options),
    [storeApi],
  );

  return { printGrid: run };
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { Printer } from "lucide-react";
import { useDataGridLabels } from "@/registry/default/components/data-grid/data-grid";
import { isDev } from "@/registry/default/components/data-grid/data-grid-sdk";
import { Button } from "@/components/ui/button";
import { useDataGridPrint } from "./use-data-grid-print";
import type { PrintGridOptions } from "./print-grid";

/** Props for {@link DataGridPrintButton}. */
export type DataGridPrintButtonProps = {
  className?: string;
  /** Print options applied to the pass; default `{ scope: "view", includeHeaders: true }`. */
  options?: PrintGridOptions;
};

/**
 * Toolbar-slot print trigger: opens the browser print dialog with the grid's rows as a plain
 * paged table (the dialog's "Save as PDF" produces the PDF). `size-8` + ghost variant matches
 * the toolbar's other icon buttons.
 */
export function DataGridPrintButton(props: DataGridPrintButtonProps): ReactNode {
  const { className, options } = props;
  const labels = useDataGridLabels();
  const { printGrid } = useDataGridPrint();
  const [busy, setBusy] = useState(false);
  const runRef = useRef<AbortController | null>(null);

  useEffect(() => () => runRef.current?.abort(), []);

  const print = () => {
    runRef.current?.abort();
    const run = new AbortController();
    runRef.current = run;
    const signal = options?.signal ? AbortSignal.any([options.signal, run.signal]) : run.signal;
    setBusy(true);
    printGrid({ ...options, signal })
      .catch((error: unknown) => {
        if (!run.signal.aborted && isDev()) console.warn("[data-grid-io] print failed", error);
      })
      .finally(() => {
        if (runRef.current !== run) return;
        runRef.current = null;
        setBusy(false);
      });
  };

  return (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      className={className}
      aria-label={labels.io.printButtonAriaLabel}
      aria-busy={busy || undefined}
      onClick={print}
    >
      <Printer />
    </Button>
  );
}

import Papa from "papaparse";
import type { CellValue } from "hucre";
import { normalizeLimit } from "./normalize-limit";

/** CSV delimiter choices exposed in the import dialog; `undefined` means auto-detect. */
export type CsvDelimiter = "," | ";" | "\t" | "|";

/**
 * Default bounds for every import. Unbounded parsing is a memory/CPU DoS vector: a tiny xlsx with
 * two far-apart cells expands to millions of cells. File size is checked before the file is read;
 * the row, column, and cell caps are checked against the real cell extent before any conversion
 * (xlsx/xls) or by the parser's own row callback and a delimiter count (CSV). A file over a cap is rejected, never truncated.
 */
export const DEFAULT_IMPORT_LIMITS = {
  /** Maximum file size in bytes; default 50 MiB. */
  maxFileBytes: 50 * 1024 * 1024,
  /** Maximum rows, header row included; default 1,000,000. */
  maxRows: 1_000_000,
  /** Maximum columns; default 1,000. */
  maxColumns: 1_000,
  /** Maximum cells, counted as rows times columns of the imported rectangle; default 5,000,000. */
  maxCells: 5_000_000,
} as const;

/** Error message {@link parseImportFile} throws for a file over `maxFileBytes`. */
export const FILE_TOO_LARGE_MESSAGE = "file-too-large";

/** Error message {@link parseImportFile} throws when one part of an xlsx file (a worksheet, the shared strings) unpacks to more than the part cap, `maxDecompressedBytes`, or `maxCells` times 10 bytes plus 1 MiB without it. */
export const PART_TOO_LARGE_MESSAGE = "part-too-large";

/** Error message {@link parseImportFile} throws when the grid exceeds `maxRows`, `maxColumns`, or `maxCells`. */
export const IMPORT_TOO_MANY_CELLS_MESSAGE = "import-too-many-cells";

/** Error message {@link parseImportFile} throws for an Excel file that is neither xlsx nor BIFF8 xls, e.g. an HTML table, Excel 2003 XML, or Excel 5.0/95. */
export const UNSUPPORTED_EXCEL_FORMAT_MESSAGE = "unsupported-excel-format";

/** Import bounds; each omitted field falls back to {@link DEFAULT_IMPORT_LIMITS}. A file over any bound is rejected, never truncated. */
export type ImportLimits = {
  /** Reject files above this size (bytes) before the file is read; default 50 MiB. */
  maxFileBytes?: number;
  /** Maximum rows, header row included; default 1,000,000. */
  maxRows?: number;
  /** Maximum columns; default 1,000. */
  maxColumns?: number;
  /** Maximum rows times columns of the imported rectangle; default 5,000,000. */
  maxCells?: number;
  /** Reject an xlsx whose parts (a worksheet, the shared strings) unpack to more than this many bytes; default `maxCells` times 10 bytes plus 1 MiB. Stops zip bombs. */
  maxDecompressedBytes?: number;
};

/** Every import bound with its default (`maxDecompressedBytes` defaults to {@link defaultPartCap}); a `NaN` bound takes the default, a negative one counts as 0. */
export function resolveImportLimits(limits: ImportLimits = {}): Required<ImportLimits> {
  const maxCells = normalizeLimit(limits.maxCells, DEFAULT_IMPORT_LIMITS.maxCells);
  return {
    maxFileBytes: normalizeLimit(limits.maxFileBytes, DEFAULT_IMPORT_LIMITS.maxFileBytes),
    maxRows: normalizeLimit(limits.maxRows, DEFAULT_IMPORT_LIMITS.maxRows),
    maxColumns: normalizeLimit(limits.maxColumns, DEFAULT_IMPORT_LIMITS.maxColumns),
    maxCells,
    maxDecompressedBytes: normalizeLimit(limits.maxDecompressedBytes, defaultPartCap(maxCells)),
  };
}

/** Options for {@link parseImportFile}. */
export type ParseImportFileOptions = ImportLimits & {
  /** Overrides CSV delimiter auto-detection; ignored for xlsx/xls. */
  csvDelimiter?: CsvDelimiter;
  /** For xlsx/xls: import this sheet by name instead of the first; rejects when the workbook has no sheet by that name. Ignored for CSV. */
  sheetName?: string;
  /** Decodes a CSV file with this label instead of UTF-8. Only the labels in {@link IMPORT_CSV_ENCODINGS} are accepted; any other label throws a `RangeError`. Ignored for xlsx/xls. */
  csvEncoding?: ImportCsvEncoding;
  /** For xlsx/xls: `"formatted"` (default) renders each cell through its number format; `"raw"` reads the stored value: a number as `String(n)`, a date as ISO 8601, a boolean as `true` or `false`, an error cell as empty. A string stays as is. Ignored for CSV. */
  valueMode?: ImportValueMode;
  /** Aborts the file read; an aborted parse rejects with an AbortError. */
  signal?: AbortSignal;
};

/** How an Excel file's cells become import text; see {@link ParseImportFileOptions.valueMode}. */
export type ImportValueMode = "formatted" | "raw";

/** The `TextDecoder` labels `csvEncoding` accepts. */
export const IMPORT_CSV_ENCODINGS = [
  "utf-8",
  "utf-16le",
  "utf-16be",
  "iso-8859-1",
  "iso-8859-2",
  "iso-8859-15",
  "windows-1250",
  "windows-1251",
  "windows-1252",
  "windows-1253",
  "windows-1254",
  "windows-1257",
  "shift_jis",
  "euc-jp",
  "euc-kr",
  "gb18030",
  "big5",
] as const;

/** A label of {@link IMPORT_CSV_ENCODINGS}; the match ignores case and surrounding spaces. */
export type ImportCsvEncoding = (typeof IMPORT_CSV_ENCODINGS)[number] | Uppercase<(typeof IMPORT_CSV_ENCODINGS)[number]>;

/** Reads a CSV file as text; a `csvEncoding` label from the allow-list decodes the bytes, otherwise the file reads as UTF-8. */
async function readCsvText(file: File, csvEncoding: ImportCsvEncoding | undefined): Promise<string> {
  if (csvEncoding === undefined) return file.text();
  const label = csvEncoding.trim().toLowerCase();
  if (!(IMPORT_CSV_ENCODINGS as readonly string[]).includes(label)) throw new RangeError(`[data-grid-io] unsupported csvEncoding: ${csvEncoding}`);
  return new TextDecoder(label).decode(await file.arrayBuffer());
}

type GridLimits = Required<Pick<ImportLimits, "maxRows" | "maxColumns" | "maxCells">>;
type ExcelLimits = GridLimits & Pick<ImportLimits, "maxDecompressedBytes">;

/** Throws the too-many-cells error when a `rows` by `columns` rectangle breaks any cap. */
function assertWithinLimits(rows: number, columns: number, limits: GridLimits): void {
  if (rows > limits.maxRows || columns > limits.maxColumns || rows * columns > limits.maxCells) {
    throw new Error(IMPORT_TOO_MANY_CELLS_MESSAGE);
  }
}

/** Normalized parse result: a plain 2D grid of strings, header row (if any) included at `rows[0]`. */
export type ParsedImportFile = {
  rows: string[][];
  /** Delimiter actually used (auto-detected or overridden); undefined for xlsx/xls. */
  delimiter?: CsvDelimiter;
  /** Every sheet name in the workbook. Undefined for CSV, or for a workbook with no sheets. */
  sheetNames?: string[];
  /** The sheet `rows` came from — the `sheetName` option, or the first sheet. Undefined for CSV. */
  sheetName?: string;
};

function isCsvFile(file: File): boolean {
  const name = file.name.toLowerCase();
  return name.endsWith(".csv") || name.endsWith(".tsv") || file.type === "text/csv" || file.type === "text/tab-separated-values";
}

function isExcelFile(file: File): boolean {
  const name = file.name.toLowerCase();
  return name.endsWith(".xlsx") || name.endsWith(".xls");
}

/** Characters papaparse sees when it guesses the delimiter and the newline. */
const CSV_SAMPLE_CHARS = 1024 * 1024;

/** The newline papaparse would guess: whichever of `\n`, `\r\n`, or `\r` ends the first line. */
function detectNewline(sample: string): "\n" | "\r\n" | "\r" {
  const cr = sample.indexOf("\r");
  const lf = sample.indexOf("\n");
  if (cr === -1 || (lf !== -1 && lf < cr)) return "\n";
  return sample[cr + 1] === "\n" ? "\r\n" : "\r";
}

/** Counts `char` in `text`: a quote-agnostic upper bound of the fields on one line, so no quoting rule is mirrored. */
function countChar(text: string, char: string): number {
  let count = 0;
  for (let at = text.indexOf(char); at !== -1; at = text.indexOf(char, at + 1)) count++;
  return count;
}

/**
 * Parses CSV text with papaparse; delimiter auto-detected unless `csvDelimiter` overrides it.
 * papaparse builds a whole row before `step` sees it, so a delimiter count above `maxCells` rejects
 * first: every field boundary is a delimiter, so one row cannot hold more fields than that. `step` then
 * stops the real parser at the first row, column, or cell breach.
 */
function parseCsvText(text: string, csvDelimiter: CsvDelimiter | undefined, limits: GridLimits): ParsedImportFile {
  const sample = text.slice(0, CSV_SAMPLE_CHARS);
  const newline = detectNewline(sample);
  const delimiter =
    csvDelimiter ?? ((Papa.parse<string[]>(sample, { preview: 10, newline, skipEmptyLines: true, delimitersToGuess: [",", ";", "	", "|"] }).meta.delimiter as CsvDelimiter | undefined) || ",");
  if (countChar(text, delimiter) > limits.maxCells) throw new Error(IMPORT_TOO_MANY_CELLS_MESSAGE);
  const rows: string[][] = [];
  let columns = 0;
  let exceeded = false;
  Papa.parse<string[]>(text, {
    delimiter,
    newline,
    skipEmptyLines: true,
    step: (result, parser) => {
      rows.push(result.data.map((cell) => cell ?? ""));
      if (result.data.length > columns) columns = result.data.length;
      if (rows.length > limits.maxRows || columns > limits.maxColumns || rows.length * columns > limits.maxCells) {
        exceeded = true;
        parser.abort();
      }
    },
  });
  if (exceeded) throw new Error(IMPORT_TOO_MANY_CELLS_MESSAGE);
  return { rows, delimiter };
}

/** Aborts the file read; rejected parses surface as an AbortError the caller can ignore. */
function abortError(): DOMException {
  return new DOMException("Aborted", "AbortError");
}

const ZIP_SIGNATURE = [0x50, 0x4b, 0x03, 0x04];
const OLE2_SIGNATURE = [0xd0, 0xcf, 0x11, 0xe0];

function hasSignature(bytes: Uint8Array, signature: readonly number[]): boolean {
  return signature.every((byte, index) => bytes[index] === byte);
}

/** The smallest cell hucre stores in a sparse read, a styled empty cell `<c s="0"/>`; each costs far more heap than XML. */
const SMALLEST_CELL_XML_BYTES = 10;

/** Room in one part for everything but cells: columns, merges, validations, formatting rules. */
const PART_OVERHEAD_BYTES = 1024 * 1024;

const UNREADABLE_ZIP_MESSAGE = "unreadable-zip";

const ZIP64_SENTINEL = 0xffffffff;

/** The part cap that applies without `maxDecompressedBytes`: `maxCells` times 10 bytes plus 1 MiB. */
export function defaultPartCap(maxCells: number): number {
  return maxCells * SMALLEST_CELL_XML_BYTES + PART_OVERHEAD_BYTES;
}

/** The largest unpacked size any one part of an xlsx may have: an explicit `maxDecompressedBytes`, else {@link defaultPartCap}. */
function partCap(limits: ExcelLimits): number {
  return limits.maxDecompressedBytes ?? defaultPartCap(limits.maxCells);
}

/**
 * Rejects a zip with any entry whose stored or declared size exceeds `cap`. Reads only the central directory,
 * and fails closed: an unreadable directory or a ZIP64 marker rejects. Hucre bounds what it inflates itself,
 * but not stored entries.
 */
function assertEntriesWithin(bytes: Uint8Array, cap: number): void {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const lowest = Math.max(0, bytes.length - 22 - 0xffff);
  let end = bytes.length - 22;
  while (end >= lowest && view.getUint32(end, true) !== 0x06054b50) end--;
  if (end < lowest) throw new Error(UNREADABLE_ZIP_MESSAGE);
  const count = view.getUint16(end + 10, true);
  let offset = view.getUint32(end + 16, true);
  if (count === 0xffff || view.getUint32(end + 12, true) === ZIP64_SENTINEL || offset === ZIP64_SENTINEL) throw new Error(PART_TOO_LARGE_MESSAGE);
  for (let i = 0; i < count; i++) {
    if (offset + 46 > bytes.length || view.getUint32(offset, true) !== 0x02014b50) throw new Error(UNREADABLE_ZIP_MESSAGE);
    const compressedSize = view.getUint32(offset + 20, true);
    const uncompressedSize = view.getUint32(offset + 24, true);
    if (compressedSize > cap || uncompressedSize > cap || compressedSize === ZIP64_SENTINEL || uncompressedSize === ZIP64_SENTINEL) throw new Error(PART_TOO_LARGE_MESSAGE);
    offset += 46 + view.getUint16(offset + 28, true) + view.getUint16(offset + 30, true) + view.getUint16(offset + 32, true);
  }
}

type HucreReader = typeof import("./xlsx-reader");
type FormatValue = HucreReader["formatValue"];
type CellVisitor = (row: number, col: number, value: CellValue, numFmt: string | undefined, isError?: boolean) => void;

/** A date without a number format (xls, ISO cells): ISO date, plus the time when it is not midnight. */
function isoDateText(date: Date, separator = " "): string {
  if (Number.isNaN(date.getTime())) return "";
  const iso = date.toISOString();
  return iso.endsWith("T00:00:00.000Z") ? iso.slice(0, 10) : iso.slice(0, 19).replace("T", separator);
}

/** A cell's stored value as text, with no number format: ISO 8601 dates, `true` or `false`, full-precision numbers. */
function rawCellText(value: CellValue, isError: boolean): string {
  if (value === null || isError) return "";
  if (typeof value === "number") return String(value);
  if (typeof value === "boolean") return String(value);
  if (value instanceof Date) return isoDateText(value, "T");
  return value;
}

/** Excel's own limit on a number format's length; hucre's format scanning grows quadratically past it. */
const MAX_NUMBER_FORMAT_LENGTH = 255;

/** A fraction denominator of four or more placeholders: hucre searches every denominator up to 10^n, about a second per cell at n = 9. */
const WIDE_FRACTION_DENOMINATOR = /\/[?#0]{4}/;

/** The format as hucre's fraction test sees it: conditions, colors, locales, and fill codes stripped, literals masked. */
function fractionView(numFmt: string): string {
  return numFmt
    .replace(/\[[<>=!]+-?\d+(?:\.\d+)?\]/g, "")
    .replace(/\[(?:Black|Blue|Cyan|Green|Magenta|Red|White|Yellow|Color\s*\d+)\]/gi, "")
    .replace(/\[\$[^\]]*\]/g, "")
    .replace(/[_*]./g, "")
    .replace(/"[^"]*"?|\\[\s\S]?/g, "\0");
}

function isSafeNumberFormat(numFmt: string): boolean {
  return numFmt.length <= MAX_NUMBER_FORMAT_LENGTH && !WIDE_FRACTION_DENOMINATOR.test(fractionView(numFmt));
}

/** The number format's rendering, or `undefined` when the format is unsafe or hucre cannot apply it. */
function formattedText(value: CellValue, numFmt: string | undefined, formatValue: FormatValue): string | undefined {
  if (numFmt === undefined || numFmt === "General" || !isSafeNumberFormat(numFmt)) return undefined;
  try {
    return formatValue(value, numFmt);
  } catch {
    return undefined;
  }
}

/** A cell's display text: its number format when it has a usable one, else Excel's General rendering. */
function cellText(value: CellValue, numFmt: string | undefined, formatValue: FormatValue): string {
  if (value === null) return "";
  const formatted = formattedText(value, numFmt, formatValue);
  if (formatted !== undefined) return formatted;
  // 15 significant digits is Excel's precision: 0.1 + 0.2 shows as 0.3
  if (typeof value === "number") return String(Number(value.toPrecision(15)));
  if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
  if (value instanceof Date) return isoDateText(value);
  return value;
}

/** Builds the string grid from A1 to the last non-empty cell, after checking that box against the limits. */
function textGrid(forEachCell: (visit: CellVisitor) => void, limits: GridLimits, formatValue: FormatValue, valueMode: ImportValueMode = "formatted"): string[][] {
  let rowCount = 0;
  let columnCount = 0;
  forEachCell((row, col, value) => {
    if (value === null) return;
    if (row >= rowCount) rowCount = row + 1;
    if (col >= columnCount) columnCount = col + 1;
  });
  assertWithinLimits(rowCount, columnCount, limits);
  const grid = Array.from({ length: rowCount }, () => new Array<string>(columnCount).fill(""));
  forEachCell((row, col, value, numFmt, isError) => {
    if (value !== null) grid[row]![col] = valueMode === "raw" ? rawCellText(value, isError === true) : cellText(value, numFmt, formatValue);
  });
  return grid;
}

/** Maps hucre's limit errors to gridcn's messages; hucre has no error codes, so its message text is matched. */
function importError(err: unknown, hucre: HucreReader): unknown {
  if (err instanceof hucre.ZipError && err.message.includes("exceeds limit")) return new Error(PART_TOO_LARGE_MESSAGE, { cause: err });
  if (err instanceof hucre.ParseError) {
    if (/over the \d+ limit|more than \d+ filled cells/.test(err.message)) return new Error(IMPORT_TOO_MANY_CELLS_MESSAGE, { cause: err });
    if (err.message.startsWith("Unsupported XLS version")) return new Error(UNSUPPORTED_EXCEL_FORMAT_MESSAGE, { cause: err });
  }
  return err;
}

/** Reads the selected sheet of an xlsx workbook. Sparse mode keeps memory proportional to the real cells, whatever their box. */
async function readXlsxSheet(
  bytes: Uint8Array,
  sheetName: string | undefined,
  limits: ExcelLimits,
  { readXlsx, formatValue }: HucreReader,
  valueMode: ImportValueMode,
): Promise<ParsedImportFile> {
  const sheetNames: string[] = [];
  const workbook = await readXlsx(bytes, {
    sheets: (info) => {
      sheetNames.push(info.name);
      return sheetName === undefined ? info.index === 0 : info.name === sheetName;
    },
    sparse: true,
    readStyles: true,
    maxDecompressedBytes: limits.maxDecompressedBytes,
  });
  if (sheetName !== undefined && !sheetNames.includes(sheetName)) throw new Error(`unknown sheet "${sheetName}"`);
  const sheet = workbook.sheets[0];
  if (!sheet) return { rows: [], sheetNames, sheetName };
  const rows = textGrid(
    (visit) => {
      for (const [key, cell] of sheet.cells ?? []) {
        const comma = key.indexOf(",");
        visit(Number(key.slice(0, comma)), Number(key.slice(comma + 1)), cell.value, cell.style?.numFmt, cell.type === "error");
      }
    },
    limits,
    formatValue,
    valueMode,
  );
  return { rows, sheetNames, sheetName: sheet.name };
}

const OLE2_END_OF_CHAIN = 0xfffffffe;
const OLE2_FREE_SECTOR = 0xffffffff;
const OLE2_SECTOR_SHIFTS = [9, 12];
const OLE2_MINI_SECTOR_SHIFT = 6;
const OLE2_DEFAULT_MINI_CUTOFF = 4096;
const OLE2_DIRECTORY_ENTRY_BYTES = 128;
const UNREADABLE_XLS_MESSAGE = "unreadable-xls";

/** Records a workbook may hold besides its cells: formats, styles, fonts, sheet metadata. */
const XLS_RECORD_SLACK = 100_000;

/** The most records an xls workbook may hold: hucre keeps about 300 bytes per record, so half a record per cell of `maxCells` stays near 0.8 GB at the defaults. */
function maxXlsRecords(maxCells: number): number {
  return maxCells / 2 + XLS_RECORD_SLACK;
}

type Ole2Entry = { name: string; type: number; start: number; size: number };

const unreadableXls = () => new Error(UNREADABLE_XLS_MESSAGE);

/**
 * The `Workbook` (or `Book`) stream of an OLE2 container, read the way hucre's reader reads it. Fails closed
 * wherever hucre would take a path the scan cannot follow: duplicate stream names, chain loops, sizes past the data.
 */
function readOle2Workbook(bytes: Uint8Array): Uint8Array {
  if (bytes.length < 512) throw unreadableXls();
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const sectorShift = view.getUint16(30, true);
  if (!OLE2_SECTOR_SHIFTS.includes(sectorShift) || view.getUint16(32, true) !== OLE2_MINI_SECTOR_SHIFT) throw unreadableXls();
  const sectorSize = 1 << sectorShift;
  const miniSectorSize = 1 << OLE2_MINI_SECTOR_SHIFT;
  const fatSectorCount = view.getUint32(44, true);
  const miniCutoff = view.getUint32(56, true) || OLE2_DEFAULT_MINI_CUTOFF;
  const miniFatSectorCount = view.getUint32(64, true);
  const difatSectorCount = view.getUint32(72, true);
  const maxSectors = Math.floor(bytes.length / sectorSize) + 1;
  const sectorAt = (sector: number) => {
    const at = (sector + 1) * sectorSize;
    if (at + sectorSize > bytes.length) throw unreadableXls();
    return at;
  };
  const fatSectors: number[] = [];
  for (let i = 0; i < 109 && fatSectors.length < fatSectorCount; i++) {
    const sector = view.getUint32(76 + i * 4, true);
    if (sector === OLE2_FREE_SECTOR || sector === OLE2_END_OF_CHAIN) break;
    fatSectors.push(sector);
  }
  const difatLimit = Math.min(difatSectorCount, maxSectors);
  let difat = view.getUint32(68, true);
  for (let hops = 0; difat !== OLE2_END_OF_CHAIN && difat !== OLE2_FREE_SECTOR && difatLimit > 0 && hops < difatLimit + 1; hops++) {
    const at = sectorAt(difat);
    for (let i = 0; i < sectorSize / 4 - 1 && fatSectors.length < fatSectorCount; i++) {
      const sector = view.getUint32(at + i * 4, true);
      if (sector !== OLE2_FREE_SECTOR && sector !== OLE2_END_OF_CHAIN) fatSectors.push(sector);
    }
    difat = view.getUint32(at + sectorSize - 4, true);
  }
  if (fatSectors.length > maxSectors || new Set(fatSectors).size !== fatSectors.length) throw unreadableXls();
  const fat = new Uint32Array((fatSectors.length * sectorSize) / 4);
  fatSectors.forEach((sector, index) => {
    const at = sectorAt(sector);
    for (let i = 0; i < sectorSize / 4; i++) fat[(index * sectorSize) / 4 + i] = view.getUint32(at + i * 4, true);
  });

  let hopsLeft = fat.length;
  const walk = (start: number): number[] => {
    const sectors: number[] = [];
    for (let sector = start; sector !== OLE2_END_OF_CHAIN && sector !== OLE2_FREE_SECTOR; sector = fat[sector] ?? OLE2_END_OF_CHAIN) {
      if (--hopsLeft < 0) throw unreadableXls();
      sectorAt(sector);
      sectors.push(sector);
    }
    return sectors;
  };
  const readChain = (start: number): Uint8Array => {
    const sectors = walk(start);
    const out = new Uint8Array(sectors.length * sectorSize);
    sectors.forEach((sector, index) => out.set(bytes.subarray(sectorAt(sector), sectorAt(sector) + sectorSize), index * sectorSize));
    return out;
  };

  const directory = readChain(view.getUint32(48, true));
  const directoryView = new DataView(directory.buffer);
  const entries: Ole2Entry[] = [];
  for (let at = 0; at + OLE2_DIRECTORY_ENTRY_BYTES <= directory.length; at += OLE2_DIRECTORY_ENTRY_BYTES) {
    const type = directory[at + 66]!;
    if (type === 0) continue;
    const nameLength = directoryView.getUint16(at + 64, true);
    let name = "";
    for (let i = 0; i + 1 < nameLength; i += 2) {
      const code = directoryView.getUint16(at + i, true);
      if (code === 0) break;
      name += String.fromCharCode(code);
    }
    entries.push({ name, type, start: directoryView.getUint32(at + 116, true), size: directoryView.getUint32(at + 120, true) });
  }
  const root = entries.find((entry) => entry.type === 5);
  if (!root) throw unreadableXls();
  const streams = entries.filter((entry) => entry.type === 2);
  const workbooks = streams.filter((entry) => entry.name === "Workbook");
  const books = streams.filter((entry) => entry.name === "Book");
  if (workbooks.length > 1 || books.length > 1) throw unreadableXls();
  const workbook = workbooks[0] ?? books[0];
  if (!workbook) throw unreadableXls();
  if (streams.reduce((total, entry) => total + entry.size, 0) > bytes.length) throw unreadableXls();

  const miniStream = readChain(root.start).subarray(0, root.size);
  const miniFatBytes =
    miniFatSectorCount > 0 && view.getUint32(60, true) !== OLE2_END_OF_CHAIN ? readChain(view.getUint32(60, true)).subarray(0, miniFatSectorCount * sectorSize) : new Uint8Array(0);
  const miniFatView = new DataView(miniFatBytes.buffer, miniFatBytes.byteOffset, miniFatBytes.byteLength);
  const miniFatLength = Math.floor(miniFatBytes.length / 4);
  let workbookBytes: Uint8Array = new Uint8Array(0);
  for (const stream of streams) {
    if (stream.size < miniCutoff) {
      if (stream.size > miniStream.length) throw unreadableXls();
      if (stream !== workbook) continue;
      workbookBytes = new Uint8Array(stream.size);
      let filled = 0;
      for (let sector = stream.start, hops = 0; filled < stream.size; sector = miniFatView.getUint32(sector * 4, true), hops++) {
        if (hops > miniFatLength || sector >= miniFatLength || (sector + 1) * miniSectorSize > miniStream.length) throw unreadableXls();
        const chunk = miniStream.subarray(sector * miniSectorSize, (sector + 1) * miniSectorSize);
        workbookBytes.set(chunk.subarray(0, stream.size - filled), filled);
        filled += chunk.length;
      }
    } else if (stream === workbook) {
      workbookBytes = readChain(stream.start).subarray(0, stream.size);
    } else {
      walk(stream.start);
    }
  }
  return workbookBytes;
}

const BIFF_BOF = 0x809;
const BIFF_EOF = 0x0a;
const BIFF_BOUNDSHEET = 0x85;
const BIFF8_VERSION = 0x600;
const BIFF_CELL_RECORDS = new Set([0xfd, 0x27e, 0x203, 0x205, 0x204, 0x06]);
const BIFF_MULRK = 0xbd;
const BIFF_MULRK_CELL_BYTES = 6;

type BiffRecord = { id: number; data: number; length: number };

/** Walks the BIFF records from `offset`, as hucre's `parseRecords` does; a record cut short by the stream end keeps the bytes that exist. */
function* biffRecords(stream: Uint8Array, view: DataView, offset: number): Generator<BiffRecord, void> {
  for (let at = offset; at + 4 <= stream.length; ) {
    const id = view.getUint16(at, true);
    const length = view.getUint16(at + 2, true);
    const data = at + 4;
    yield { id, data, length: Math.min(length, stream.length - data) };
    if (id === 0 && length === 0) return;
    at = data + length;
  }
}

/** How many records hucre's `parseRecords` would build, counted without building them; stops at `cap + 1`. */
function biffRecordCount(stream: Uint8Array, view: DataView, cap: number): number {
  let count = 0;
  for (let at = 0; at + 4 <= stream.length && count <= cap; count++) {
    const length = view.getUint16(at + 2, true);
    if (length === 0 && view.getUint16(at, true) === 0) return count + 1;
    at += 4 + length;
  }
  return count;
}

/** The cells a worksheet substream spans, and where its records end; reads on from the record after `start`, as hucre does, and stops once the span passes `cap`. */
function biffSheetBox(stream: Uint8Array, view: DataView, start: number, cap: number): { cells: number; end: number } {
  let rows = 0;
  let columns = 0;
  let end = start;
  let atStart = true;
  for (const { id, data, length } of biffRecords(stream, view, start)) {
    end = data + length;
    if (atStart) {
      atStart = false;
      continue;
    }
    if (id === BIFF_EOF) break;
    const mulrk = id === BIFF_MULRK;
    if (length < 4 || !(mulrk || BIFF_CELL_RECORDS.has(id))) continue;
    let lastColumn = view.getUint16(data + 2, true);
    if (mulrk) {
      if (length < 6) continue;
      const cells = (length - 6) / BIFF_MULRK_CELL_BYTES;
      if (!Number.isInteger(cells)) throw unreadableXls();
      if (cells === 0) continue;
      lastColumn += cells - 1;
    }
    rows = Math.max(rows, view.getUint16(data, true) + 1);
    columns = Math.max(columns, lastColumn + 1);
    if (rows * columns > cap) break;
  }
  return { cells: rows * columns, end };
}

// hucre pads every sheet and builds one object per record; bound both before it runs.
function assertXlsWithinLimits(bytes: Uint8Array, limits: GridLimits): void {
  const stream = readOle2Workbook(bytes);
  const view = new DataView(stream.buffer, stream.byteOffset, stream.byteLength);
  if (biffRecordCount(stream, view, maxXlsRecords(limits.maxCells)) > maxXlsRecords(limits.maxCells)) throw new Error(IMPORT_TOO_MANY_CELLS_MESSAGE);
  const sheetStarts: number[] = [];
  let atStart = true;
  for (const { id, data, length } of biffRecords(stream, view, 0)) {
    if (atStart) {
      if (id !== BIFF_BOF || (length >= 2 && view.getUint16(data, true) !== BIFF8_VERSION)) return;
      atStart = false;
      continue;
    }
    if (id === BIFF_EOF) break;
    if (id === BIFF_BOUNDSHEET && length >= 4) sheetStarts.push(view.getUint32(data, true));
  }
  const boxes = new Map<number, number>();
  let total = 0;
  let scanBudget = stream.length;
  for (const start of sheetStarts) {
    if (!boxes.has(start)) {
      const { cells, end } = biffSheetBox(stream, view, start, limits.maxCells);
      scanBudget -= end - start;
      if (scanBudget < 0) throw unreadableXls();
      boxes.set(start, cells);
    }
    total += boxes.get(start)!;
    if (total > limits.maxCells) throw new Error(IMPORT_TOO_MANY_CELLS_MESSAGE);
  }
}

/** Reads a BIFF8 `.xls` workbook; hucre parses every sheet, each bounded by `maxCells`, and returns values without number formats. */
async function readXlsSheet(
  bytes: Uint8Array,
  sheetName: string | undefined,
  limits: GridLimits,
  { readXls, formatValue }: HucreReader,
  valueMode: ImportValueMode,
): Promise<ParsedImportFile> {
  assertXlsWithinLimits(bytes, limits);
  const workbook = await readXls(bytes, { maxTotalCells: limits.maxCells });
  const sheetNames = workbook.sheets.map((sheet) => sheet.name);
  const selected = sheetName !== undefined ? sheetNames.indexOf(sheetName) : 0;
  if (selected === -1) throw new Error(`unknown sheet "${sheetName}"`);
  const sheet = workbook.sheets[selected];
  if (!sheet) return { rows: [], sheetNames, sheetName };
  const rows = textGrid((visit) => sheet.rows.forEach((row, r) => row.forEach((value, c) => visit(r, c, value, undefined))), limits, formatValue, valueMode);
  return { rows, sheetNames, sheetName: sheet.name };
}

/** Parses one sheet of an xlsx/xls workbook into a 2D string grid via lazily-imported hucre; `sheetName` selects the sheet (first by default). The file's signature, not its extension, picks the reader. */
async function parseExcelFile(file: File, sheetName: string | undefined, limits: ExcelLimits, valueMode: ImportValueMode, signal?: AbortSignal): Promise<ParsedImportFile> {
  const bytes = new Uint8Array(await file.arrayBuffer());
  if (signal?.aborted) throw abortError();
  const isXlsx = hasSignature(bytes, ZIP_SIGNATURE);
  if (!isXlsx && !hasSignature(bytes, OLE2_SIGNATURE)) throw new Error(UNSUPPORTED_EXCEL_FORMAT_MESSAGE);
  const partBytes = partCap(limits);
  const parseLimits = isXlsx ? { ...limits, maxDecompressedBytes: partBytes } : limits;
  if (isXlsx) assertEntriesWithin(bytes, partBytes);
  const hucre = await import("./xlsx-reader");
  try {
    return await (isXlsx ? readXlsxSheet : readXlsSheet)(bytes, sheetName, parseLimits, hucre, valueMode);
  } catch (err) {
    throw importError(err, hucre);
  }
}

/**
 * Parses a `.csv`, `.tsv`, `.xlsx`, or `.xls` file into a normalized 2D string grid. CSV/TSV goes
 * through papaparse (delimiter auto-detect + override); Excel formats go through a
 * dynamically-imported hucre (it never loads for CSV-only consumers), the `sheetName` sheet
 * or the first one. `.xls` means Excel 97-2003 (BIFF8); other `.xls` flavours reject. `signal`
 * aborts the file read when set; an aborted parse rejects with an AbortError.
 */
export async function parseImportFile(file: File, options: ParseImportFileOptions = {}): Promise<ParsedImportFile> {
  const { signal } = options;
  const { maxFileBytes, maxDecompressedBytes, ...limits } = resolveImportLimits(options);
  // before any file read: file.size is synchronous, so the DoS check costs nothing
  if (file.size > maxFileBytes) throw new Error(FILE_TOO_LARGE_MESSAGE);
  if (isExcelFile(file)) {
    return parseExcelFile(file, options.sheetName, { ...limits, maxDecompressedBytes }, options.valueMode === "raw" ? "raw" : "formatted", signal);
  }
  if (isCsvFile(file)) {
    const text = await readCsvText(file, options.csvEncoding);
    if (signal?.aborted) throw abortError();
    const parsed = parseCsvText(text, options.csvDelimiter, limits);
    let columns = 0;
    for (const row of parsed.rows) if (row.length > columns) columns = row.length;
    assertWithinLimits(parsed.rows.length, columns, limits);
    return parsed;
  }
  throw new Error("unsupported-file-type");
}

/** Thrown for a parse result or row hook output that is not an array of string rows. */
export const INVALID_IMPORT_ROWS_MESSAGE = "invalid-import-rows";

/**
 * Checks rows that came from a consumer hook (`parseFile`, `processImportRows`): an array of arrays of
 * strings inside the `maxRows`, `maxColumns`, and `maxCells` bounds. `extraRows` counts rows the caller
 * holds beside `rows` (a header row). Throws {@link INVALID_IMPORT_ROWS_MESSAGE} or the too-many-cells error.
 */
export function assertImportRows(rows: unknown, limits: ImportLimits, extraRows = 0): asserts rows is string[][] {
  if (!Array.isArray(rows)) throw new Error(INVALID_IMPORT_ROWS_MESSAGE);
  const { maxRows, maxColumns, maxCells } = resolveImportLimits(limits);
  const bounds: GridLimits = { maxRows, maxColumns, maxCells };
  let columns = 0;
  for (const row of rows as unknown[]) {
    if (!Array.isArray(row)) throw new Error(INVALID_IMPORT_ROWS_MESSAGE);
    if (row.length > columns) columns = row.length;
    if (columns > bounds.maxColumns) throw new Error(IMPORT_TOO_MANY_CELLS_MESSAGE);
    for (const cell of row as unknown[]) if (typeof cell !== "string") throw new Error(INVALID_IMPORT_ROWS_MESSAGE);
  }
  assertWithinLimits(rows.length + extraRows, columns, bounds);
}

// A static re-export per direction lets bundlers tree-shake hucre's barrels inside the lazy chunk.
export { readXls, readXlsx } from "hucre/xlsx";
export { formatValue, ParseError, ZipError } from "hucre";

import type { GateContext } from "@/registry/default/components/data-grid/data-grid";
import { columnLabelText, isThenable } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { CsvDelimiter, ImportValueMode } from "./parse-import-file";

/** Minimal column shape the header-matching/preview logic needs — matches `ColumnDef` structurally. */
export type ImportTargetColumn = { id: string; headerText?: string; header: unknown };

/**
 * Consumer-configurable defaults applied at PRESELECTION time only — the user can always
 * override any of these in the dialog once it's open.
 */
export type ImportDefaults = {
  /** Skip auto-detect and preselect this delimiter. Detect still runs if undefined. */
  defaultDelimiter?: CsvDelimiter;
  /** How an Excel file's cells become text: `"formatted"` (default) applies number formats, `"raw"` reads stored values (see `ParseImportFileOptions.valueMode`). */
  valueMode?: ImportValueMode;
  /** Default for the header-row toggle. A number is the 0-based index of the header row: the rows above it are dropped, and that row is the header. `true` is `0`. Default `true`. */
  defaultHeaderRow?: boolean | number;
  /** Source columns to preselect as skipped: header names (case-insensitive) or indices. */
  defaultSkipColumns?: readonly (string | number)[];
  /**
   * Override the initial mapping per source column; return undefined to fall back to the
   * built-in matcher, null to skip. Wins over `defaultSkipColumns`. A promise holds the mapping
   * until it settles; a rejection falls back to the built-in matcher. `signal` aborts when a newer
   * parse of the dialog supersedes this one or the dialog unmounts; an aborted mapping is dropped.
   * Inside a grid, `gateTimeoutMs.mapColumn` aborts a pending mapping and falls back to the built-in matcher.
   */
  mapColumn?: (header: string, index: number, ctx: GateContext) => string | null | undefined | Promise<string | null | undefined>;
};

function firstWins(columns: readonly ImportTargetColumn[], keyOf: (column: ImportTargetColumn) => string): Map<string, string> {
  const map = new Map<string, string>();
  for (const column of columns) {
    const key = keyOf(column);
    if (!map.has(key)) map.set(key, column.id);
  }
  return map;
}

/**
 * Prefills the import-column -> grid-column mapping by matching each imported header against
 * `column.headerText ?? header ?? column.id`, case-insensitively. Unmatched headers map to `null`
 * (the dialog's '—' skip option). Each grid column can only be claimed once — a later duplicate
 * match falls back to `null` (skip) since one-source-per-grid-column is enforced everywhere.
 */
export function matchImportColumns(importHeaders: readonly string[], gridColumns: readonly ImportTargetColumn[]): (string | null)[] {
  const byLowerText = firstWins(gridColumns, (column) => columnLabelText(column).toLowerCase());
  const byLowerId = firstWins(gridColumns, (column) => column.id.toLowerCase());

  const claimed = new Set<string>();
  return importHeaders.map((header) => {
    const key = header.trim().toLowerCase();
    const gridColumnId = byLowerText.get(key) ?? byLowerId.get(key) ?? null;
    if (gridColumnId === null || claimed.has(gridColumnId)) return null;
    claimed.add(gridColumnId);
    return gridColumnId;
  });
}

/** True when `defaultSkipColumns` names `header` (case-insensitive) or `index` (0-based). */
function isDefaultSkipped(header: string, index: number, defaultSkipColumns: readonly (string | number)[]): boolean {
  const key = header.trim().toLowerCase();
  return defaultSkipColumns.some((entry) => (typeof entry === "number" ? entry === index : entry.trim().toLowerCase() === key));
}

/**
 * Preselects the import-column -> grid-column mapping: starts from {@link matchImportColumns},
 * then applies `options.defaultSkipColumns` (by header name or index), then `options.mapColumn`
 * per column (wins over `defaultSkipColumns`; `undefined` keeps whatever came before it). All of
 * this only decides the dialog's *initial* mapping — the user can still change every cell by hand
 * once the dialog is open. A grid column that two import columns claim stays with the first
 * one, whether the matcher or `mapColumn` named it; the later import column maps to `null`.
 */
export function applyImportOptions(
  importHeaders: readonly string[],
  gridColumns: readonly ImportTargetColumn[],
  options: { defaultSkipColumns?: readonly (string | number)[]; mapColumn?: (header: string, index: number) => string | null | undefined } = {},
): (string | null)[] {
  return resolveImportMapping(importHeaders, gridColumns, options) as (string | null)[];
}

/** {@link applyImportOptions} for a `mapColumn` that may answer with a promise: a Promise when any column does, else the plain array. */
export function resolveImportMapping(
  importHeaders: readonly string[],
  gridColumns: readonly ImportTargetColumn[],
  options: Pick<ImportDefaults, "defaultSkipColumns" | "mapColumn"> & { signal?: AbortSignal } = {},
): (string | null)[] | Promise<(string | null)[]> {
  const { defaultSkipColumns, mapColumn } = options;
  const gateCtx: GateContext = { signal: options.signal ?? new AbortController().signal };
  const matched = matchImportColumns(importHeaders, gridColumns);
  const overridden = matched.map((gridColumnId, index) => {
    const header = importHeaders[index] ?? "";
    return defaultSkipColumns && isDefaultSkipped(header, index, defaultSkipColumns) ? null : gridColumnId;
  });
  const overrides = matched.map((_, index) => mapColumn?.(importHeaders[index] ?? "", index, gateCtx));
  const combine = (resolved: readonly (string | null | undefined)[]) => {
    const claimed = new Set<string>();
    return overridden.map((kept, index) => {
      const id = resolved[index] === undefined ? kept : resolved[index]!;
      if (id === null || claimed.has(id)) return null;
      claimed.add(id);
      return id;
    });
  };
  return overrides.some((override) => isThenable(override)) ? Promise.all(overrides).then(combine) : combine(overrides as (string | null | undefined)[]);
}

import type { AnyColumnDef, CellType, ColumnDef, GateContext } from "@/registry/default/components/data-grid/data-grid";
import type { ValidateBatchItem, ValidateResult } from "@/registry/default/components/data-grid/data-grid-sdk";
import { createWarnOnce, isDev, isThenable, parseWithHook, resolveColumnValidate, runValidateBatch, safeFromText, settleHookFailure, setCellValue, validateContextsFor } from "@/registry/default/components/data-grid/data-grid-sdk";

/** One import-column -> grid-column mapping entry; `null` skips the import column. */
export type ImportColumnMapping = { importColumnIndex: number; gridColumnId: string | null };

/** Above this row count, `buildImportedRows` yields between chunks so the dialog stays responsive and Cancel can land. */
export const IMPORT_CHUNK_THRESHOLD_ROWS = 5_000;

/** Rows processed per chunk once {@link IMPORT_CHUNK_THRESHOLD_ROWS} is exceeded. */
const CHUNK_SIZE = 2_000;

/** One import cell whose value failed `column.validate`: the cell is cleared with its cell type's `clearValue()`, and the row is still imported. */
export type ImportRejectedCell = {
  /** 0-based index into `dataRows` (header row excluded). */
  rowIndex: number;
  /** 0-based index of the source column in the import file. */
  importColumnIndex: number;
  /** The grid column the value was mapped to and cleared in. */
  gridColumnId: string;
  /** The validator's reason, cut at {@link MAX_REJECTED_MESSAGE_LENGTH} characters. */
  message?: string;
};

/** Longest validator message an {@link ImportRejectedCell} keeps. */
export const MAX_REJECTED_MESSAGE_LENGTH = 200;

/** Replaces `cellType.fromText` for one import cell. The returned value still goes through the column's `validate`. */
export type ProcessCellFromText<TData> = (
  text: string,
  ctx: {
    /** The row as `createRow` returned it. */
    row: TData;
    column: ColumnDef<TData, unknown, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
    source: "import";
    signal: AbortSignal;
    /** The column's own parser, for the cells you do not change. */
    fromText: (text: string) => unknown;
  },
) => unknown;

/** Result of {@link buildImportedRows}: the built rows plus every rejected (cleared) cell. */
export type BuildImportedRowsResult<TData> = {
  rows: TData[];
  /** Cells whose value failed `column.validate` and was cleared. Their rows are still built. */
  rejected: ImportRejectedCell[];
  /** Cells of `validationMode: "warn"` columns whose value failed validation. The value stays in its row, uncleared. */
  flagged: ImportRejectedCell[];
};

/** Inputs for {@link buildImportedRows}. */
export type BuildImportedRowsOptions<TData> = {
  /** Data rows only (header row, if any, already excluded by the caller). */
  dataRows: readonly string[][];
  mapping: readonly ImportColumnMapping[];
  // ColumnDef's 3rd param (TValidate) erases to `any`, not `unknown` — see data-grid/store.tsx's
  // AnyColumnDef doc: validate's function-or-schema union can't stay bivariant as a plain property.
  columns: readonly ColumnDef<TData, unknown, any>[]; // eslint-disable-line @typescript-eslint/no-explicit-any
  cellTypes: Record<string, CellType<TData, unknown, unknown>>;
  /** Builds a fresh row for import row `index`; required — the dialog never writes to the grid store directly. A promise makes the build a Promise; a rejection rejects it. `ctx.signal` is `options.signal`. */
  createRow: (index: number, ctx: GateContext) => TData | Promise<TData>;
  /** Parses one cell instead of `cellType.fromText`; may return a promise, which makes the build asynchronous. Its value is validated like any other. */
  processCellFromText?: ProcessCellFromText<TData>;
  /** Checked between chunks on the chunked path (above {@link IMPORT_CHUNK_THRESHOLD_ROWS} rows, or with `processCellFromText`) and after an async `createRow`; an aborted signal throws `"import-cancelled"`. A small synchronous build ignores it. */
  signal?: AbortSignal;
  /** The rows the import joins. `unique()` compares each imported value with them and with the other imported rows. The default append passes the grid's `data`. Default `[]`. */
  existingRows?: readonly TData[];
  /** Runs once per built row after the build parses its cells, like the grid's `validateRow`. A verdict entry for a mapped column clears that cell and lands in `rejected`; an entry for an unmapped column lands in `flagged` with `importColumnIndex` `-1`. A throw or a rejection gives that row no verdict. Rows run in chunks, so `signal` cancels between chunks. */
  validateRow?: (row: TData, rowId: string, ctx: GateContext) => Record<string, string> | null | undefined | Promise<Record<string, string> | null | undefined>;
  /** The id `validateRow` receives for built row `index`. Default: `String(index)`. */
  getRowId?: (row: TData, index: number) => string;
};

/** One import cell awaiting its validation verdict: where it goes, and what to write if the value is rejected. */
type ImportCell = {
  rowIndex: number;
  importColumnIndex: number;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- same TValidate erasure as BuildImportedRowsOptions.columns.
  column: ColumnDef<any, unknown, any>;
  clearedValue: unknown;
  warn: boolean;
};

/** Thrown from the chunked path when `options.signal` is aborted between chunks. */
export const IMPORT_CANCELLED_MESSAGE = "import-cancelled";

/**
 * Builds `TData` rows from parsed import rows: one `createRow(index)` per row, then each mapped
 * cell is parsed through its column's cell type `fromText` and checked by `column.validate` (or the
 * cell type's `validate`) — invalid values are cleared via `clearValue()` rather than dropping the
 * whole row, and every rejected cell is listed in the result's `rejected`.
 *
 * Always returns a Promise, and a throw rejects it. Imports above {@link IMPORT_CHUNK_THRESHOLD_ROWS} rows
 * (or with `processCellFromText`) are built in chunks that yield to the event loop, so the dialog repaints
 * and `options.signal` can cancel between chunks. Async validators run with the shared chunked concurrency cap.
 *
 * The function form's second argument is the row as `createRow` returned it, not the row with this
 * import row's earlier columns already folded in — validating a whole import row concurrently and
 * validating it left to right cannot both be true, and the fresh row is the predictable one.
 */
export async function buildImportedRows<TData>(options: BuildImportedRowsOptions<TData>): Promise<BuildImportedRowsResult<TData>> {
  const built = await buildNow(options);
  return options.validateRow ? validateBuiltRows(built, options, options.validateRow) : built;
}

/** Validation yields to the event loop after this much work; a timer turn costs up to 16 ms on Windows. */
const VALIDATE_YIELD_AFTER_MS = 40;

type Verdict = Record<string, string> | null | undefined;

/** Runs `validateRow` over the built rows, `CHUNK_SIZE` rows at a time. A verdict reads only the keys of known columns, so a hostile object costs at most one lookup per column. */
async function validateBuiltRows<TData>(
  built: BuildImportedRowsResult<TData>,
  options: BuildImportedRowsOptions<TData>,
  validateRow: NonNullable<BuildImportedRowsOptions<TData>["validateRow"]>,
): Promise<BuildImportedRowsResult<TData>> {
  const { rows, rejected, flagged } = built;
  const { columns, cellTypes, mapping, signal = NEVER_ABORTED, getRowId = (_row, index) => String(index) } = options;
  const gateCtx: GateContext = { signal };
  const importIndexOf = new Map<string, number>();
  for (const m of mapping) if (m.gridColumnId !== null && !importIndexOf.has(m.gridColumnId)) importIndexOf.set(m.gridColumnId, m.importColumnIndex);

  let lastYield = performance.now();
  for (let start = 0; start < rows.length; start += CHUNK_SIZE) {
    if (signal.aborted) throw new Error(IMPORT_CANCELLED_MESSAGE);
    const end = Math.min(start + CHUNK_SIZE, rows.length);
    const verdicts = new Array<Verdict>(end - start);
    const settling: Promise<void>[] = [];
    for (let offset = 0; offset < end - start; offset++) {
      const row = rows[start + offset]!;
      try {
        const verdict = validateRow(row, getRowId(row, start + offset), gateCtx);
        if (isThenable(verdict)) settling.push(Promise.resolve(verdict as Promise<Verdict>).then((value) => void (verdicts[offset] = value), () => undefined));
        else verdicts[offset] = verdict;
      } catch {
        // a throw gives the row no verdict
      }
    }
    if (settling.length > 0) await Promise.all(settling);
    if (signal.aborted) throw new Error(IMPORT_CANCELLED_MESSAGE);
    verdicts.forEach((verdict, offset) => {
      if (!verdict || typeof verdict !== "object") return;
      const rowIndex = start + offset;
      for (const column of columns) {
        if (!Object.hasOwn(verdict, column.id) || typeof verdict[column.id] !== "string") continue;
        const message = verdict[column.id]!.slice(0, MAX_REJECTED_MESSAGE_LENGTH);
        const importColumnIndex = importIndexOf.get(column.id);
        const cellType = cellTypes[column.type ?? "text"];
        if (importColumnIndex === undefined || !cellType) {
          flagged.push({ rowIndex, importColumnIndex: -1, gridColumnId: column.id, message });
          continue;
        }
        // as never: setCellValue is typed against this column's own TData/TValue, which TS can't unify with the generic TData/unknown here
        rows[rowIndex] = setCellValue(rows[rowIndex] as never, column as never, cellType.clearValue(column.options) as never) as TData;
        rejected.push({ rowIndex, importColumnIndex, gridColumnId: column.id, message });
      }
    });
    if (performance.now() - lastYield > VALIDATE_YIELD_AFTER_MS) {
      await yieldToEventLoop();
      lastYield = performance.now();
    }
  }
  return built;
}

function buildNow<TData>(options: BuildImportedRowsOptions<TData>): BuildImportedRowsResult<TData> | Promise<BuildImportedRowsResult<TData>> {
  const { dataRows, mapping, columns, cellTypes, createRow, signal, processCellFromText, existingRows = [] } = options;
  const columnsById = new Map(columns.map((column) => [column.id, column] as const));
  const seenColumns = new Set<string>();
  const warnedColumns = new Set<string>();
  const activeMappings = mapping.filter((m): m is { importColumnIndex: number; gridColumnId: string } => {
    if (m.gridColumnId === null) return false;
    if (!seenColumns.has(m.gridColumnId)) {
      seenColumns.add(m.gridColumnId);
      return true;
    }
    if (isDev() && !warnedColumns.has(m.gridColumnId)) {
      warnedColumns.add(m.gridColumnId);
      console.warn(`[data-grid-io] buildImportedRows: grid column "${m.gridColumnId}" is mapped by more than one import column - the first mapping wins`);
    }
    return false;
  });

  if (dataRows.length > IMPORT_CHUNK_THRESHOLD_ROWS || processCellFromText) {
    return buildImportedRowsChunked(dataRows, activeMappings, columnsById, cellTypes, createRow, signal ?? new AbortController().signal, existingRows, processCellFromText);
  }

  const gateCtx: GateContext = { signal: signal ?? new AbortController().signal };
  const created = dataRows.map((_, index) => createRow(index, gateCtx));
  if (created.some((row) => isThenable(row))) {
    return Promise.all(created).then((rows) => {
      if (signal?.aborted) throw new Error(IMPORT_CANCELLED_MESSAGE);
      return finishSmallImport(dataRows, activeMappings, columnsById, cellTypes, rows, existingRows);
    });
  }
  return finishSmallImport(dataRows, activeMappings, columnsById, cellTypes, created as TData[], existingRows);
}

function finishSmallImport<TData>(
  dataRows: readonly string[][],
  activeMappings: readonly ResolvedMapping[],
  columnsById: ReadonlyMap<string, ColumnDef<TData, unknown, any>>, // eslint-disable-line @typescript-eslint/no-explicit-any
  cellTypes: Record<string, CellType<TData, unknown, unknown>>,
  rows: TData[],
  existingRows: readonly TData[],
): BuildImportedRowsResult<TData> | Promise<BuildImportedRowsResult<TData>> {
  const rejected: ImportRejectedCell[] = [];
  const flagged: ImportRejectedCell[] = [];
  const { items, cells } = buildCellsForRange(dataRows, 0, dataRows.length, activeMappings, columnsById, cellTypes, rows);
  attachValidateContexts(items, cells, existingRows);
  const results = runValidateBatch(items);
  if (results instanceof Promise) return results.then((resolved) => ({ rows: writeCells(rows, cells, items, resolved, rejected, flagged), rejected, flagged }));
  return { rows: writeCells(rows, cells, items, results, rejected, flagged), rejected, flagged };
}

/** One resolved mapping entry: the source column index paired with its target column definition. */
type ResolvedMapping = { importColumnIndex: number; gridColumnId: string };

// shortcut: a chunked import (past one chunk) checks each chunk's cells as one batch; a duplicate across chunks passes. Upgrade: settle every chunk's values before validating.
/** Gives each function `validate` the imported cells of its column as the batch, over the rows the import joins. */
function attachValidateContexts(items: ValidateBatchItem[], cells: readonly ImportCell[], existingRows: readonly unknown[]): void {
  const contexts = validateContextsFor(existingRows, cells.map((cell) => cell.column as AnyColumnDef), cells.map((cell, i) => ({ columnId: cell.column.id, row: items[i]!.row, value: items[i]!.value })));
  cells.forEach((cell, i) => (items[i]!.ctx = contexts.get(cell.column.id)));
}

/** Builds `rows[start, end)`'s validation items/cells against the already-created `rows` array. */
function buildCellsForRange<TData>(
  dataRows: readonly string[][],
  start: number,
  end: number,
  activeMappings: readonly ResolvedMapping[],
  columnsById: ReadonlyMap<string, ColumnDef<TData, unknown, any>>, // eslint-disable-line @typescript-eslint/no-explicit-any
  cellTypes: Record<string, CellType<TData, unknown, unknown>>,
  rows: TData[],
  processCellFromText?: ProcessCellFromText<TData>,
  signal: AbortSignal = NEVER_ABORTED,
): { items: ValidateBatchItem[]; cells: ImportCell[] } {
  const items: ValidateBatchItem[] = [];
  const cells: ImportCell[] = [];
  for (let rowIndex = start; rowIndex < end; rowIndex++) {
    const sourceRow = dataRows[rowIndex]!; // start/end are within dataRows.length by construction
    for (const { importColumnIndex, gridColumnId } of activeMappings) {
      const column = columnsById.get(gridColumnId);
      if (!column) continue;
      const cellType = cellTypes[column.type ?? "text"];
      if (!cellType) continue;

      const text = sourceRow[importColumnIndex] ?? "";
      // as never: validate is typed against this column's own TData/TValue, which TS can't unify with the generic TData/unknown here — safe since column and row/value are all this same import's TData.
      const columnValidate = resolveColumnValidate(column as AnyColumnDef, cellType);
      const parsed = processCellFromText
        ? parseWithHook("processCellFromText", () => processCellFromText(text, { row: rows[rowIndex] as TData, column, source: "import", signal, fromText: (raw) => cellType.fromText(raw, column.options) }), columnValidate, warnOnceFor(processCellFromText))
        : safeFromText(cellType, text, column.options, columnValidate);
      items.push({ validate: parsed.validate as never, value: parsed.value, row: rows[rowIndex] });
      cells.push({ rowIndex, importColumnIndex, column, clearedValue: cellType.clearValue(column.options), warn: column.validationMode === "warn" });
    }
  }
  return { items, cells };
}

const hookWarnings = new WeakMap<object, ReturnType<typeof createWarnOnce>>();

function warnOnceFor(hook: object): ReturnType<typeof createWarnOnce> {
  let warnOnce = hookWarnings.get(hook);
  if (!warnOnce) hookWarnings.set(hook, (warnOnce = createWarnOnce()));
  return warnOnce;
}

const NEVER_ABORTED = new AbortController().signal;

/** Awaits every item whose value a `processCellFromText` hook returned as a promise. */
async function settleItemValues(items: ValidateBatchItem[]): Promise<void> {
  const pending: Promise<void>[] = [];
  items.forEach((item, index) => {
    if (isThenable(item.value)) pending.push(Promise.resolve(item.value).then((value) => void (items[index] = settleHookFailure({ ...items[index]!, value }))));
  });
  if (pending.length > 0) await Promise.all(pending);
}

/** Yields to the event loop; a chunk boundary for both the main-thread-block fix and the Cancel affordance. */
function yieldToEventLoop(): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve));
}

/**
 * Large-import path: builds and writes rows {@link CHUNK_SIZE} at a time, yielding between chunks so
 * the dialog's pending state actually repaints and `signal` gets a chance to cancel. Validation still
 * runs once per chunk (not once for the whole import) so a huge async-schema import doesn't hold
 * `CHUNK_SIZE`-multiples of items in flight at once.
 */
async function buildImportedRowsChunked<TData>(
  dataRows: readonly string[][],
  activeMappings: readonly ResolvedMapping[],
  columnsById: ReadonlyMap<string, ColumnDef<TData, unknown, any>>, // eslint-disable-line @typescript-eslint/no-explicit-any
  cellTypes: Record<string, CellType<TData, unknown, unknown>>,
  createRow: (index: number, ctx: GateContext) => TData | Promise<TData>,
  signal: AbortSignal,
  existingRows: readonly TData[],
  processCellFromText?: ProcessCellFromText<TData>,
): Promise<BuildImportedRowsResult<TData>> {
  const gateCtx: GateContext = { signal };
  const created = dataRows.map((_, index) => createRow(index, gateCtx));
  const rows = created.some((row) => isThenable(row)) ? await Promise.all(created) : (created as TData[]);
  const rejected: ImportRejectedCell[] = [];
  const flagged: ImportRejectedCell[] = [];

  for (let start = 0; start < dataRows.length; start += CHUNK_SIZE) {
    if (signal?.aborted) throw new Error(IMPORT_CANCELLED_MESSAGE);
    const end = Math.min(start + CHUNK_SIZE, dataRows.length);
    const { items, cells } = buildCellsForRange(dataRows, start, end, activeMappings, columnsById, cellTypes, rows, processCellFromText, signal);
    await settleItemValues(items);
    if (signal?.aborted) throw new Error(IMPORT_CANCELLED_MESSAGE);
    attachValidateContexts(items, cells, existingRows);
    const results = await runValidateBatch(items);
    writeCells(rows, cells, items, results, rejected, flagged);
    await yieldToEventLoop();
  }
  if (signal?.aborted) throw new Error(IMPORT_CANCELLED_MESSAGE);

  return { rows, rejected, flagged };
}

function rejectionMessage(result: ValidateResult): string | undefined {
  if (!("error" in result) || typeof result.error !== "string" || result.error === "") return undefined;
  return result.error.slice(0, MAX_REJECTED_MESSAGE_LENGTH);
}

/**
 * Folds each verdict into its row: the validator's output on success, the cell type's `clearValue()`
 * on rejection (the rejected cell is appended to `rejected`). `cells` is grouped by `rowIndex`
 * (built in mapping order per row), so a run of
 * consecutive plain-`accessorKey` cells for the same row is merged into one spread instead of one
 * spread per cell — this was the measured hot spot, one spread + 2 temp objects per cell at scale.
 * The run is flushed (a) before a `setValue` cell in the same row, so `setValue` still sees every
 * earlier cell's write, exactly as the un-merged left-to-right spreads did, and (b) at each row
 * boundary. A column with a custom `setValue` keeps writing through `setCellValue` per cell, since
 * only `setValue` knows how to fold its own value into the row.
 */
function writeCells<TData>(
  rows: TData[],
  cells: readonly ImportCell[],
  items: readonly { value: unknown }[],
  results: readonly ValidateResult[],
  rejected: ImportRejectedCell[],
  flagged: ImportRejectedCell[],
): TData[] {
  let pendingRow = -1;
  let pendingPatch: Record<string, unknown> | null = null;
  const flush = () => {
    if (pendingPatch === null) return;
    // as TData: TData is generic here, but pendingPatch's keys are this same TData's own accessorKeys — mirrors setCellValue's own accessorKey-spread branch.
    rows[pendingRow] = { ...rows[pendingRow], ...pendingPatch } as TData;
    pendingPatch = null;
  };

  for (let i = 0; i < cells.length; i++) {
    const cell = cells[i]!; // i < cells.length by loop condition
    const result = results[i];
    if (!result) continue;
    const isRejected = "error" in result;
    const keepsValue = isRejected && cell.warn && !result.thrown;
    if (isRejected) (keepsValue ? flagged : rejected).push({ rowIndex: cell.rowIndex, importColumnIndex: cell.importColumnIndex, gridColumnId: cell.column.id, message: rejectionMessage(result) });
    const value = keepsValue ? items[i]!.value : isRejected ? cell.clearedValue : result.value;

    if (cell.rowIndex !== pendingRow) flush();
    pendingRow = cell.rowIndex;

    if (!cell.column.setValue && cell.column.accessorKey) {
      pendingPatch ??= {};
      pendingPatch[cell.column.accessorKey] = value;
      continue;
    }
    flush();
    // as never: setCellValue is typed against this column's own TData/TValue, which TS can't unify with the generic TData/unknown here — safe since column and row/value are all this same import's TData.
    rows[cell.rowIndex] = setCellValue(rows[cell.rowIndex] as never, cell.column as never, value as never) as TData;
  }
  flush();
  return rows;
}

import { isDev } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { ImportColumnMapping, ImportRejectedCell } from "./build-imported-rows";

/** Longest refusal message the import check keeps. */
export const MAX_CHECK_MESSAGE_LENGTH = 200;

/** Refusals the import check reads; the rest count as "and more". */
export const MAX_CHECK_REFUSALS = 1_000;

/** One row the server refuses. `rowIndex` is the 0-based index into the rows `checkImport` received. */
export type ImportCheckRefusal = { rowIndex: number; columnId?: string; message?: string };

/** Counts a server reports for the rows it checked. */
export type ImportCheckSummary = { created?: number; updated?: number; skipped?: number };

/** What `checkImport` returns. An answer without refusals lets the import go on. */
export type ImportCheckAnswer = { rejected?: ImportCheckRefusal[]; summary?: ImportCheckSummary };

/** What `checkImport` receives besides the rows. */
export type ImportCheckContext = {
  /** Aborts when the user cancels, the dialog closes, or a new file loads. Pass it to your request. */
  signal: AbortSignal;
  /** Which file column went to which grid column. */
  mapping: readonly ImportColumnMapping[];
  fileName: string;
  /** The sheet the rows came from; undefined for CSV. */
  sheetName?: string;
  /** Cells whose value failed `column.validate`; each was cleared and its row is in the rows. */
  rejected: readonly ImportRejectedCell[];
};

/** Checks the built rows before they are saved; see {@link ImportCheckAnswer}. */
export type CheckImport<TData> = (rows: TData[], ctx: ImportCheckContext) => ImportCheckAnswer | void | Promise<ImportCheckAnswer | void>;

/** The read answer: `failed` for a shape the check does not accept, else the bounded refusals. */
export type ImportCheck = { status: "failed" } | { status: "checked"; refusals: ImportCheckRefusal[]; more: number; summary?: ImportCheckSummary };

const FAILED: ImportCheck = { status: "failed" };

const isRecord = (value: unknown): value is Record<string, unknown> => typeof value === "object" && value !== null && !Array.isArray(value);

const isCount = (value: unknown): value is number => typeof value === "number" && Number.isInteger(value) && value >= 0;

function readSummary(value: unknown): ImportCheckSummary | null | undefined {
  if (value === undefined) return undefined;
  if (!isRecord(value)) return null;
  const summary: ImportCheckSummary = {};
  for (const key of ["created", "updated", "skipped"] as const) {
    const count = value[key];
    if (count === undefined) continue;
    if (!isCount(count)) return null;
    summary[key] = count;
  }
  return summary;
}

function readRefusal(entry: unknown, rowCount: number, columnIds: ReadonlySet<string>): ImportCheckRefusal | null {
  if (!isRecord(entry)) return null;
  const rowIndex = entry["rowIndex"], columnId = entry["columnId"], message = entry["message"];
  if (typeof rowIndex !== "number" || !Number.isInteger(rowIndex) || rowIndex < 0 || rowIndex >= rowCount) return null;
  if (columnId !== undefined && typeof columnId !== "string") return null;
  if (message !== undefined && typeof message !== "string") return null;
  const refusal: ImportCheckRefusal = { rowIndex };
  if (columnId !== undefined && columnIds.has(columnId)) refusal.columnId = columnId;
  if (message !== undefined) refusal.message = message.slice(0, MAX_CHECK_MESSAGE_LENGTH);
  return refusal;
}

/**
 * Reads an untrusted `checkImport` answer: at most {@link MAX_CHECK_REFUSALS} refusals, each `rowIndex`
 * inside `rowCount`, `columnId` kept only for a live column, `message` cut. Any other shape is `failed`.
 */
export function readImportCheckAnswer(answer: unknown, rowCount: number, columnIds: ReadonlySet<string>): ImportCheck {
  try {
    if (answer === undefined || answer === null) return { status: "checked", refusals: [], more: 0 };
    if (!isRecord(answer)) return FAILED;
    const summary = readSummary(answer["summary"]);
    if (summary === null) return FAILED;
    const rejected = answer["rejected"];
    if (rejected !== undefined && !Array.isArray(rejected)) return FAILED;
    const refusals: ImportCheckRefusal[] = [];
    const read = Math.min(rejected?.length ?? 0, MAX_CHECK_REFUSALS);
    for (let i = 0; i < read; i++) {
      const refusal = readRefusal(rejected![i], rowCount, columnIds);
      if (!refusal) return FAILED;
      refusals.push(refusal);
    }
    return { status: "checked", refusals, more: Math.max((rejected?.length ?? 0) - read, 0), ...(summary && { summary }) };
  } catch {
    return FAILED;
  }
}

/** Runs `checkImport` over built rows and reads the answer. A throw or a rejection is `failed`, except an abort, which rethrows. */
export async function runImportCheck<TData>(checkImport: CheckImport<TData>, rows: TData[], ctx: ImportCheckContext, columnIds: ReadonlySet<string>): Promise<ImportCheck> {
  try {
    return readImportCheckAnswer(await checkImport(rows, ctx), rows.length, columnIds);
  } catch (error) {
    if (ctx.signal.aborted) throw error;
    if (isDev()) console.warn("[data-grid-io] checkImport failed", error);
    return FAILED;
  }
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  FILE_TOO_LARGE_MESSAGE,
  IMPORT_TOO_MANY_CELLS_MESSAGE,
  PART_TOO_LARGE_MESSAGE,
  UNSUPPORTED_EXCEL_FORMAT_MESSAGE,
  assertImportRows,
  parseImportFile,
  resolveImportLimits,
  type CsvDelimiter,
  type ImportCsvEncoding,
  type ImportLimits,
  type ImportValueMode,
  type ParsedImportFile,
} from "./parse-import-file";
import { resolveImportMapping, type ImportTargetColumn, type ImportDefaults } from "./match-import-column";
import { runImportCheck, type CheckImport, type ImportCheck } from "./import-check";
import { buildImportedRows, IMPORT_CANCELLED_MESSAGE, type BuildImportedRowsOptions, type BuildImportedRowsResult, type ImportColumnMapping } from "./build-imported-rows";
import { DEFAULT_LABELS, type AnyCellType } from "@/registry/default/components/data-grid/data-grid";
import { isDev, isThenable, useOptionalDataGridColumnSource, useOptionalDataGridGateTracker, useOptionalDataGridLabels, type GateTracker } from "@/registry/default/components/data-grid/data-grid-sdk";

export type { ImportTargetColumn, ImportDefaults };

/** Rows shown in the preview table, capped for readability. */
export const IMPORT_PREVIEW_ROW_COUNT = 10;

/** Keys into `labels.io` for the parse-failure messages {@link useDataGridImportPreview} can surface. */
export type ImportErrorKey = "errorParseFailed" | "errorNoRows" | "errorUnsupportedFile" | "errorUnsupportedExcelFormat" | "errorFileTooLarge" | "errorPartTooLarge" | "errorTooManyCells";

/** Error thrown by {@link parseImportFile} for extensions outside csv/xlsx/xls. */
const UNSUPPORTED_FILE_TYPE_MESSAGE = "unsupported-file-type";

/** True when a parse was aborted (new file chosen, dialog closed) — the caller drops the result instead of surfacing an error. */
function isAbortError(err: unknown): boolean {
  return err instanceof Error && err.name === "AbortError";
}

/** Maps a parse failure to its dialog error key; null for aborts the caller drops silently. */
export function importErrorKey(err: unknown): ImportErrorKey | null {
  if (isAbortError(err)) return null;
  if (err instanceof Error) {
    switch (err.message) {
      case UNSUPPORTED_FILE_TYPE_MESSAGE:
        return "errorUnsupportedFile";
      case UNSUPPORTED_EXCEL_FORMAT_MESSAGE:
        return "errorUnsupportedExcelFormat";
      case FILE_TOO_LARGE_MESSAGE:
        return "errorFileTooLarge";
      case PART_TOO_LARGE_MESSAGE:
        return "errorPartTooLarge";
      case IMPORT_TOO_MANY_CELLS_MESSAGE:
        return "errorTooManyCells";
    }
  }
  return "errorParseFailed";
}

/** Parsed-and-ready import state, once a file has been chosen and parsed successfully. */
export type ImportFileState = {
  fileName: string;
  /** All parsed rows, including the header row (if `hasHeaderRow`) at index 0. */
  rows: string[][];
  hasHeaderRow: boolean;
  /** Display header per column: the file's header row text, or `labels.io.columnFallback(N)` when there's no header row. */
  importHeaders: string[];
  mapping: ImportColumnMapping[];
  delimiter?: CsvDelimiter;
  /** Every sheet name in the workbook. Undefined for CSV. Lets a consumer offer a sheet picker when a workbook has more than one sheet. */
  sheetNames?: string[];
  /** The sheet `rows` came from (first by default, or the one selected via {@link UseDataGridImportPreviewResult.setSheetName}). Undefined for CSV. */
  sheetName?: string;
};

/** Return value of {@link useDataGridImportPreview}. */
export type UseDataGridImportPreviewResult = {
  preview: ImportFileState | null;
  error: ImportErrorKey | null;
  /** True while a file is being read/parsed. */
  isParsing: boolean;
  /** Parses `file`; on success populates `preview` with column mapping prefilled by header-text match. */
  loadFile: (file: File, gridColumns: readonly ImportTargetColumn[]) => Promise<void>;
  setHasHeaderRow: (hasHeaderRow: boolean) => void;
  /** Re-parses the current CSV file with the given delimiter override; no-op for xlsx/xls files or before a file is loaded. A failed re-parse sets `error` instead of throwing. */
  setDelimiter: (delimiter: CsvDelimiter) => Promise<void>;
  /**
   * Re-parses the current xlsx/xls workbook with the given sheet; no-op for CSV or before a file
   * is loaded. Switching sheets recomputes the column mapping from scratch (different headers), so
   * any manual mapping the user set on the previous sheet is discarded.
   */
  setSheetName: (sheetName: string) => Promise<void>;
  setMapping: (importColumnIndex: number, gridColumnId: string | null) => void;
  reset: () => void;
  /** Data rows only (header row excluded when `hasHeaderRow`), capped to `IMPORT_PREVIEW_ROW_COUNT` for the preview table. */
  previewRows: string[][];
  /** All data rows (header row excluded when `hasHeaderRow`) — the full set `onImport` will build from. */
  importRows: string[][];
  /**
   * Builds the `TData` rows from the current preview: `processImportRows` (when given), then
   * `buildImportedRows` with the current mapping. Returns `null` when `processImportRows` returned
   * `false` or there is no preview yet. A hook result outside the import limits rejects with the
   * too-many-cells error. Always returns a Promise.
   */
  build: <TData>(options: BuildImportOptions<TData>) => Promise<ImportBuildResult<TData> | null>;
};

/** Result of {@link UseDataGridImportPreviewResult.build}: with `checkImport`, `check` holds the read answer. */
export type ImportBuildResult<TData> = BuildImportedRowsResult<TData> & { check?: ImportCheck };

/** Builds display headers: the file's header row when present, else `labels.io.columnFallback(N)`. */
function computeImportHeaders(rows: string[][], hasHeaderRow: boolean, columnFallback: (index: number) => string): string[] {
  const columnCount = rows[0]?.length ?? 0;
  if (hasHeaderRow && rows[0]) return rows[0];
  return Array.from({ length: columnCount }, (_, i) => columnFallback(i + 1));
}

/** Options for {@link useDataGridImportPreview}. */
export type UseDataGridImportPreviewOptions = {
  /** Builds the header shown for column N when the file has no header row. Default: `labels.io.columnFallback` of the enclosing grid, else the built-in label. */
  columnFallback?: (index: number) => string;
  /** Preselection defaults (see {@link ImportDefaults}). */
  defaults?: ImportDefaults;
  /** Size, row, column, cell, and unpacked-size bounds for every parse; omitted fields use `DEFAULT_IMPORT_LIMITS`. */
  limits?: ImportLimits;
  /** Reads the file instead of the built-in parser, for every parse (file load, delimiter, sheet). A file over `maxFileBytes` is rejected before the hook runs. Its rows must be arrays of strings inside `limits`, which are checked after the hook. `csvEncoding` does not apply. */
  parseFile?: ParseFile;
  /** Decodes a CSV file with this `TextDecoder` label instead of UTF-8; see `IMPORT_CSV_ENCODINGS` for the accepted labels. */
  csvEncoding?: ImportCsvEncoding;
};

const MAX_SHEET_NAMES = 256;
const MAX_SHEET_NAME_CHARS = 255;

/** Up to {@link MAX_SHEET_NAMES} distinct strings from the first entries of `names`; a huge list is not scanned to the end. */
function uniqueSheetNames(names: readonly unknown[]): string[] {
  const unique = new Set<string>();
  const scanLimit = Math.min(names.length, MAX_SHEET_NAMES * 4);
  for (let index = 0; index < scanLimit && unique.size < MAX_SHEET_NAMES; index++) {
    const name = names[index];
    if (typeof name === "string") unique.add(name.slice(0, MAX_SHEET_NAME_CHARS));
  }
  return [...unique];
}

const CSV_DELIMITERS: readonly CsvDelimiter[] = [",", ";", "\t", "|"];

/** Keeps only the fields of a custom parse result that the dialog reads, and bounds the lists and strings in them. */
function sanitizeParsedFile(parsed: ParsedImportFile): ParsedImportFile {
  const delimiter = CSV_DELIMITERS.includes(parsed.delimiter as CsvDelimiter) ? parsed.delimiter : undefined;
  const sheetNames = Array.isArray(parsed.sheetNames) ? uniqueSheetNames(parsed.sheetNames) : undefined;
  const sheetName = typeof parsed.sheetName === "string" ? parsed.sheetName.slice(0, MAX_SHEET_NAME_CHARS) : undefined;
  return { rows: parsed.rows, delimiter, sheetNames, sheetName };
}

/** Replaces the built-in file parser; see {@link UseDataGridImportPreviewOptions.parseFile}. */
export type ParseFile = (
  file: File,
  ctx: { signal: AbortSignal; limits: Required<ImportLimits>; sheetName?: string; csvDelimiter?: CsvDelimiter; valueMode: ImportValueMode },
) => ParsedImportFile | Promise<ParsedImportFile>;

/** Rewrites or drops the data rows before they are mapped and built; see {@link UseDataGridImportPreviewResult.build}. */
export type ProcessImportRows = (ctx: {
  /** The data rows, header row excluded. */
  rows: string[][];
  /** The header text of each source column. */
  headers: string[];
  mapping: ImportColumnMapping[];
  signal: AbortSignal;
}) => string[][] | false | Promise<string[][] | false>;

/** Inputs of {@link UseDataGridImportPreviewResult.build} besides the file state the hook already holds. */
export type BuildImportOptions<TData> = Omit<BuildImportedRowsOptions<TData>, "dataRows" | "mapping" | "columns" | "cellTypes"> & {
  /** The columns the rows are built for. Default: the columns of the enclosing grid. */
  columns?: BuildImportedRowsOptions<TData>["columns"];
  /** The cell types that parse each cell. Default: the resolved cell types of the enclosing grid, which `useDataGridCellTypes()` returns. */
  cellTypes?: Record<string, AnyCellType>;
  /** Runs on the data rows before the mapping is applied. `false` cancels the import: `build()` resolves `null`. The result is checked against the import limits. */
  processImportRows?: ProcessImportRows;
  /** Checks the built rows on your server before they are saved; the answer lands in `result.check`. A throw or a rejection gives `{ status: "failed" }`. Absent: no check. */
  checkImport?: CheckImport<TData>;
};

type MappingGate = { signal: AbortSignal; arm: () => void; stop: () => void };

/** The `mapColumn` signal: aborts with `signal`, or through the grid's gate run (`gateTimeoutMs.mapColumn`) once {@link MappingGate.arm} holds it. */
function mappingGate(signal: AbortSignal, gates: GateTracker | null): MappingGate {
  const run = gates?.begin("mapColumn");
  return {
    signal: run ? AbortSignal.any([signal, run.signal]) : signal,
    arm: () => run && gates!.hold(run),
    stop: () => run && gates!.settle(run),
  };
}

/** Awaits a promised mapping until it settles or `gate` aborts; a rejected or timed-out `mapColumn` falls back to the built-in match so the dialog still opens. */
async function settleMapping(
  mapped: Promise<(string | null)[]>,
  fallback: () => (string | null)[],
  gate: MappingGate,
): Promise<(string | null)[]> {
  gate.arm();
  const aborted = new Promise<never>((_, reject) => gate.signal.addEventListener("abort", () => reject(gate.signal.reason), { once: true }));
  try {
    return await Promise.race([mapped, aborted]);
  } catch (error) {
    if (isDev() && !gate.signal.aborted) console.warn("[data-grid-io] mapColumn rejected, so the built-in column match is used", error);
    return fallback();
  } finally {
    gate.stop();
  }
}

/**
 * Owns the parse -> preview -> column-mapping state for the import dialog. File I/O and header
 * matching are pure functions ({@link parseImportFile}, {@link applyImportOptions}); this hook only
 * sequences them and exposes editable dialog state (header-row toggle, delimiter, per-column mapping).
 *
 */
export function useDataGridImportPreview(options: UseDataGridImportPreviewOptions = {}): UseDataGridImportPreviewResult {
  const gridLabels = useOptionalDataGridLabels();
  const grid = useOptionalDataGridColumnSource();
  const gates = useOptionalDataGridGateTracker();
  const mapGate = useCallback((signal: AbortSignal) => mappingGate(signal, gates), [gates]);
  const gridColumns = grid?.columns;
  const gridCellTypes = grid?.cellTypes;
  const labelsIo = (gridLabels ?? DEFAULT_LABELS).io;
  const columnFallback = options.columnFallback ?? labelsIo.columnFallback;
  const { defaults = {}, limits = {}, parseFile, csvEncoding } = options;
  const [preview, setPreview] = useState<ImportFileState | null>(null);
  const [error, setError] = useState<ImportErrorKey | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  // kept for delimiter-override re-parses, which need the original file + target columns again.
  const currentFileRef = useRef<File | null>(null);
  const gridColumnsRef = useRef<readonly ImportTargetColumn[]>([]);
  // aborts an in-flight file read when a newer load starts or the dialog resets.
  const parseControllerRef = useRef<AbortController | null>(null);
  // generation guard for every async parse (file load, sheet switch, delimiter override): a newer parse or reset wins over a slower older one.
  const parseGenerationRef = useRef(0);
  const { defaultHeaderRow = true, defaultSkipColumns, mapColumn } = defaults;
  const valueMode: ImportValueMode = defaults.valueMode === "raw" ? "raw" : "formatted";
  const headerRowIndex = typeof defaultHeaderRow === "number" ? Math.max(0, Math.floor(defaultHeaderRow) || 0) : 0;
  const initialHasHeaderRow = defaultHeaderRow !== false;
  // the header-row toggle as the async mapping steps read it; they cannot read a state updater's `prev`.
  const hasHeaderRowRef = useRef(initialHasHeaderRow);
  const parseFileRef = useRef(parseFile);
  useEffect(() => {
    parseFileRef.current = parseFile;
  });
  const { maxFileBytes, maxRows, maxColumns, maxCells, maxDecompressedBytes } = limits;
  const limitOptions = useMemo(
    () => ({ maxFileBytes, maxRows, maxColumns, maxCells, maxDecompressedBytes }),
    [maxFileBytes, maxRows, maxColumns, maxCells, maxDecompressedBytes],
  );

  useEffect(
    () => () => {
      parseGenerationRef.current += 1;
      parseControllerRef.current?.abort();
    },
    [],
  );

  const startParse = useCallback((): { generation: number; controller: AbortController } => {
    const generation = ++parseGenerationRef.current;
    parseControllerRef.current?.abort();
    const controller = new AbortController();
    parseControllerRef.current = controller;
    return { generation, controller };
  }, []);

  const effectiveLimits = useMemo<Required<ImportLimits>>(
    () => resolveImportLimits({ maxFileBytes, maxRows, maxColumns, maxCells, maxDecompressedBytes }),
    [maxFileBytes, maxRows, maxColumns, maxCells, maxDecompressedBytes],
  );

  /** One parse: the consumer's `parseFile` (its result checked against the limits) or the built-in parser; rows above the header-row index are dropped. */
  const parse = useCallback(
    async (file: File, extra: { sheetName?: string; csvDelimiter?: CsvDelimiter }, signal?: AbortSignal): Promise<ParsedImportFile> => {
      const custom = parseFileRef.current;
      let parsed: ParsedImportFile;
      if (custom) {
        if (file.size > effectiveLimits.maxFileBytes) throw new Error(FILE_TOO_LARGE_MESSAGE);
        const checked = await custom(file, { signal: signal ?? new AbortController().signal, limits: effectiveLimits, valueMode, ...extra });
        if (typeof checked !== "object" || checked === null) throw new Error("invalid-import-rows");
        assertImportRows(checked.rows, effectiveLimits);
        parsed = sanitizeParsedFile(checked);
      } else {
        parsed = await parseImportFile(file, { ...limitOptions, csvEncoding, valueMode, ...extra, signal });
      }
      return headerRowIndex > 0 ? { ...parsed, rows: parsed.rows.slice(headerRowIndex) } : parsed;
    },
    [effectiveLimits, limitOptions, csvEncoding, headerRowIndex, valueMode],
  );

  const reset = useCallback(() => {
    parseGenerationRef.current += 1;
    parseControllerRef.current?.abort();
    setPreview(null);
    setError(null);
    setIsParsing(false);
    currentFileRef.current = null;
    gridColumnsRef.current = [];
  }, []);

  const loadFile = useCallback(async (file: File, gridColumns: readonly ImportTargetColumn[]) => {
    // a re-parse started while this file loads has no file to re-parse, so it cannot outlive this load
    currentFileRef.current = null;
    const { generation, controller } = startParse();
    setError(null);
    setIsParsing(true);
    try {
      const parsed = await parse(file, { csvDelimiter: defaults.defaultDelimiter }, controller.signal);
      if (generation !== parseGenerationRef.current) return; // superseded by a newer file load or a reset
      if (parsed.rows.length === 0) {
        setError("errorNoRows");
        setPreview(null);
        return;
      }
      currentFileRef.current = file;
      gridColumnsRef.current = gridColumns;
      const hasHeaderRow = initialHasHeaderRow;
      hasHeaderRowRef.current = hasHeaderRow;
      const importHeaders = computeImportHeaders(parsed.rows, hasHeaderRow, columnFallback);
      const gate = mapGate(controller.signal);
      const mapped = resolveImportMapping(importHeaders, gridColumns, { defaultSkipColumns, mapColumn, signal: gate.signal });
      const matched = isThenable(mapped)
        ? await settleMapping(mapped, () => resolveImportMapping(importHeaders, gridColumns, { defaultSkipColumns }) as (string | null)[], gate)
        : (gate.stop(), mapped);
      if (generation !== parseGenerationRef.current) return; // superseded while mapColumn was pending
      setPreview({
        fileName: file.name,
        rows: parsed.rows,
        hasHeaderRow,
        importHeaders,
        mapping: matched.map((gridColumnId, importColumnIndex) => ({ importColumnIndex, gridColumnId })),
        delimiter: parsed.delimiter,
        sheetNames: parsed.sheetNames,
        sheetName: parsed.sheetName,
      });
    } catch (err) {
      const key = importErrorKey(err);
      if (key === null || generation !== parseGenerationRef.current) return; // superseded by a newer file or a dialog reset
      setError(key);
      setPreview(null);
    } finally {
      // a superseded (aborted) load must not clear the newer load's parsing state
      if (parseControllerRef.current === controller) setIsParsing(false);
    }
    // oxlint-disable-next-line react-hooks/exhaustive-deps -- destructured option fields are the real deps; `defaults` itself may be a fresh object each render.
  }, [columnFallback, initialHasHeaderRow, defaultSkipColumns, mapColumn, mapGate, parse, startParse]);

  const mapForReparse = useCallback(
    (importHeaders: readonly string[], signal: AbortSignal): (string | null)[] | Promise<(string | null)[]> => {
      const gridColumns = gridColumnsRef.current;
      const gate = mapGate(signal);
      const mapped = resolveImportMapping(importHeaders, gridColumns, { defaultSkipColumns, mapColumn, signal: gate.signal });
      return isThenable(mapped)
        ? settleMapping(mapped, () => resolveImportMapping(importHeaders, gridColumns, { defaultSkipColumns }) as (string | null)[], gate)
        : (gate.stop(), mapped);
    },
    [defaultSkipColumns, mapColumn, mapGate],
  );

  const setHasHeaderRow = useCallback(
    (hasHeaderRow: boolean) => {
      hasHeaderRowRef.current = hasHeaderRow;
      setPreview((prev) => {
        if (!prev) return prev;
        const importHeaders = computeImportHeaders(prev.rows, hasHeaderRow, columnFallback);
        return { ...prev, hasHeaderRow, importHeaders };
      });
    },
    [columnFallback],
  );

  const setDelimiter = useCallback(
    async (delimiter: CsvDelimiter) => {
      const file = currentFileRef.current;
      if (!file) return;
      const { generation, controller } = startParse();
      setError(null);
      setIsParsing(true);
      try {
        const parsed = await parse(file, { csvDelimiter: delimiter }, controller.signal);
        if (generation !== parseGenerationRef.current) return; // superseded by a newer file load, sheet switch, or reset
        if (parsed.rows.length === 0) return;
        const importHeaders = computeImportHeaders(parsed.rows, hasHeaderRowRef.current, columnFallback);
        const mappedHeaders = mapForReparse(importHeaders, controller.signal);
        const matched = isThenable(mappedHeaders) ? await mappedHeaders : mappedHeaders;
        if (generation !== parseGenerationRef.current) return; // superseded while mapColumn was pending
        setPreview((prev) => {
          if (!prev) return prev;
          return {
            ...prev,
            rows: parsed.rows,
            importHeaders,
            delimiter,
            mapping: matched.map((gridColumnId, importColumnIndex) => ({ importColumnIndex, gridColumnId })),
          };
        });
      } catch (err) {
        const key = importErrorKey(err);
        if (key === null) return;
        if (generation === parseGenerationRef.current) setError(key);
      } finally {
        if (generation === parseGenerationRef.current) setIsParsing(false);
      }
    },
    [columnFallback, mapForReparse, parse, startParse],
  );

  const setSheetName = useCallback(
    async (sheetName: string) => {
      const file = currentFileRef.current;
      if (!file) return;
      const { generation, controller } = startParse();
      setError(null);
      setIsParsing(true);
      try {
        const parsed = await parse(file, { sheetName }, controller.signal);
        if (generation !== parseGenerationRef.current) return; // superseded by a newer sheet switch, file load, or reset
        if (parsed.rows.length === 0) {
          // empty sheet: the picker keeps the chosen name honest, the preview clears, Import stays disabled
          setPreview((prev) =>
            prev ? { ...prev, rows: [], importHeaders: [], mapping: [], sheetName: parsed.sheetName ?? sheetName } : prev,
          );
          setError("errorNoRows");
          return;
        }
        const importHeaders = computeImportHeaders(parsed.rows, hasHeaderRowRef.current, columnFallback);
        const mappedHeaders = mapForReparse(importHeaders, controller.signal);
        const matched = isThenable(mappedHeaders) ? await mappedHeaders : mappedHeaders;
        if (generation !== parseGenerationRef.current) return; // superseded while mapColumn was pending
        setPreview((prev) => {
          if (!prev) return prev;
          return {
            ...prev,
            rows: parsed.rows,
            importHeaders,
            sheetName: parsed.sheetName,
            mapping: matched.map((gridColumnId, importColumnIndex) => ({ importColumnIndex, gridColumnId })),
          };
        });
      } catch (err) {
        const key = importErrorKey(err);
        if (key === null) return;
        if (generation === parseGenerationRef.current) setError(key);
      } finally {
        if (generation === parseGenerationRef.current) setIsParsing(false);
      }
    },
    [columnFallback, mapForReparse, parse, startParse],
  );

  const setMapping = useCallback((importColumnIndex: number, gridColumnId: string | null) => {
    setPreview((prev) => {
      if (!prev) return prev;
      const mapping = prev.mapping.map((m) =>
        m.importColumnIndex === importColumnIndex ? { ...m, gridColumnId } : gridColumnId !== null && m.gridColumnId === gridColumnId ? { ...m, gridColumnId: null } : m,
      );
      return { ...prev, mapping };
    });
  }, []);

  const importRows = useMemo(() => {
    if (!preview) return [];
    return preview.hasHeaderRow ? preview.rows.slice(1) : preview.rows;
  }, [preview]);

  const previewRows = useMemo(() => importRows.slice(0, IMPORT_PREVIEW_ROW_COUNT), [importRows]);

  const warnedNoPreviewRef = useRef(false);
  const build = useCallback(
    async <TData,>(buildOptions: BuildImportOptions<TData>): Promise<ImportBuildResult<TData> | null> => {
      if (!preview) {
        if (isDev() && !warnedNoPreviewRef.current) {
          warnedNoPreviewRef.current = true;
          console.warn("[data-grid-io] build() ran before a file was loaded and returns null; call loadFile() first");
        }
        return null;
      }
      const { processImportRows, checkImport, columns, cellTypes, ...rest } = buildOptions;
      if (!(columns && cellTypes) && !gridColumns && isDev()) console.warn("[data-grid-io] build() found no grid; pass `columns` and `cellTypes` or call it under a DataGridProvider");
      const signal = rest.signal ?? new AbortController().signal;
      const buildColumns = columns ?? ((gridColumns ?? []) as BuildImportedRowsOptions<TData>["columns"]);
      const finish = async (dataRows: string[][]): Promise<ImportBuildResult<TData>> => {
        const built = await buildImportedRows<TData>({
          ...rest,
          columns: buildColumns,
          cellTypes: (cellTypes ?? gridCellTypes ?? {}) as BuildImportedRowsOptions<TData>["cellTypes"],
          signal: rest.signal,
          dataRows,
          mapping: preview.mapping,
        });
        if (!checkImport) return built;
        const ctx = { signal, mapping: preview.mapping, fileName: preview.fileName, sheetName: preview.sheetName, rejected: built.rejected };
        const check = await runImportCheck(checkImport, built.rows, ctx, new Set(buildColumns.map((column) => column.id)));
        if (signal.aborted) throw new Error(IMPORT_CANCELLED_MESSAGE);
        return { ...built, check };
      };
      if (!processImportRows) return finish(importRows);
      const hooked = processImportRows({ rows: importRows, headers: preview.importHeaders, mapping: preview.mapping, signal });
      const accept = (result: string[][] | false): ImportBuildResult<TData> | null | Promise<ImportBuildResult<TData>> => {
        if (signal.aborted) throw new Error(IMPORT_CANCELLED_MESSAGE);
        if (result === false) return null;
        assertImportRows(result, effectiveLimits, preview.hasHeaderRow ? 1 : 0);
        return finish(result);
      };
      return isThenable(hooked) ? Promise.resolve(hooked).then(accept) : accept(hooked);
    },
    [preview, importRows, effectiveLimits, gridColumns, gridCellTypes],
  );

  return { preview, error, isParsing, loadFile, setHasHeaderRow, setDelimiter, setSheetName, setMapping, reset, previewRows, importRows, build };
}

"use client";

import { Fragment, useCallback, useEffect, useId, useMemo, useRef, useState, type ReactNode } from "react";
import { Paperclip, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { useDataGridActions, useDataGridAllColumns, useDataGridLabels, type GateContext } from "@/registry/default/components/data-grid/data-grid";
import { columnLabelText, isDev, useDataGridFlaggedCommit, useDataGridMarkGatePending, useDataGridSelector, useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { IMPORT_CANCELLED_MESSAGE, type BuildImportedRowsOptions, type ImportColumnMapping, type ImportRejectedCell, type ProcessCellFromText } from "./build-imported-rows";
import { importErrorKey, useDataGridImportPreview, type ImportTargetColumn, type ImportDefaults, type ParseFile, type ProcessImportRows, type ImportErrorKey } from "./use-data-grid-import";
import type { CheckImport, ImportCheckRefusal, ImportCheckSummary } from "./import-check";
import { resolveImportLimits, type CsvDelimiter, type ImportCsvEncoding, type ImportLimits } from "./parse-import-file";
import { acceptedTypeNames, Dropzone, DropzoneEmptyState, type DropzoneAccept, type DropzoneRejection } from "@/registry/default/components/dropzone/dropzone";

/** Accepted import file types, shared by the file input and the {@link Dropzone}. */
const IMPORT_ACCEPT: DropzoneAccept = {
  "text/csv": [".csv"],
  "text/tab-separated-values": [".tsv"],
  "application/vnd.ms-excel": [".xls"],
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": [".xlsx"],
};

export type { ImportDefaults };

const DELIMITER_OPTIONS: { value: CsvDelimiter; labelKey: "delimiterComma" | "delimiterSemicolon" | "delimiterTab" | "delimiterPipe" }[] = [
  { value: ",", labelKey: "delimiterComma" },
  { value: ";", labelKey: "delimiterSemicolon" },
  { value: "\t", labelKey: "delimiterTab" },
  { value: "|", labelKey: "delimiterPipe" },
];

/** Mapping-select value for a source column that maps to no grid column. */
const SKIP_VALUE = "__skip__";

/** What `onImport` receives beside the rows. */
export type ImportContext = {
  /** Aborts when the user cancels or the dialog closes. Pass it to your request. */
  signal: AbortSignal;
  /** Cells whose value failed `column.validate`; each was cleared and its row is in `rows`. */
  rejected: readonly ImportRejectedCell[];
  /** Cells of `validationMode: "warn"` columns whose value failed `validate`; each keeps its value in `rows`. The default append flags them in `cellErrors`. */
  flagged: readonly ImportRejectedCell[];
  fileName: string;
  /** The sheet the rows came from; undefined for CSV. */
  sheetName?: string;
  /** Which file column went to which grid column. */
  mapping: readonly ImportColumnMapping[];
};

/** The file facts `onImport` gets, taken when the user confirms. */
type ImportSource = Pick<ImportContext, "fileName" | "sheetName" | "mapping">;

/** Maximum characters of an `onImport` error message the dialog shows. */
const MAX_ERROR_MESSAGE_LENGTH = 200;

const hasUnloadedRows = (data: readonly unknown[]): boolean => {
  for (let i = 0; i < data.length; i++) if (data[i] === undefined) return true;
  return false;
};

type AppendBlock = "importNeedsOnImport" | "importReadOnly";

const appendBlockOf = (state: { readOnly: boolean; totalRowCount?: number | null }): AppendBlock | null =>
  state.readOnly ? "importReadOnly" : state.totalRowCount !== undefined ? "importNeedsOnImport" : null;

/** The label key that explains why import is unavailable: a read-only grid takes no import, and the default append needs a client grid, so a grid without `onImport` that holds a server result gets one. */
export function useImportBlock(onImport: unknown, open = true): AppendBlock | null {
  const block = useDataGridSelector<unknown, AppendBlock | null>(appendBlockOf);
  const data = useDataGridSelector<unknown, readonly unknown[]>((s) => s.data as readonly unknown[]);
  const sparse = useMemo(() => open && !onImport && hasUnloadedRows(data), [open, onImport, data]);
  return onImport && block !== "importReadOnly" ? null : (block ?? (sparse ? "importNeedsOnImport" : null));
}

/** Props for {@link DataGridImportDialog}. */
export type DataGridImportDialogProps<TData> = {
  /** Merges into the dialog content, which is `max-h-[80vh]` and `sm:max-w-2xl` by default. */
  className?: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Builds a fresh row for import row `index`; required. */
  createRow: (index: number, ctx: GateContext) => TData | Promise<TData>;
  /** Called with the fully-built rows on confirm; the consumer decides how to merge (replace, upsert, or a server call). Default: appends the rows to `data` as one undoable `"import"` change. A grid with `totalRowCount` holds a window of its result, so it has no default and needs this prop. Cells rejected by `validate` are already cleared in these rows. May be async (e.g. a server upsert) — the dialog stays pending until it settles and surfaces a rejection instead of closing. `ctx.signal` aborts when the user cancels or the dialog closes; pass it to your request. */
  onImport?: (rows: TData[], ctx: ImportContext) => void | Promise<void>;
  /** Called once when `onImport` rejects, with the rejection. The dialog stays open. */
  onImportError?: (error: unknown) => void;
  /** Consumer-configurable preselection defaults (delimiter, header row, skip columns, mapping). Omit to keep the built-in detection. */
  importDefaults?: ImportDefaults;
  /** Size, row, column, cell, and unpacked-size bounds for the file; omitted fields use `DEFAULT_IMPORT_LIMITS`. `maxFileBytes` also sets the drop zone's `maxSize`. */
  importLimits?: ImportLimits;
  /** Reads the file instead of the built-in parser. Its rows are checked against `importLimits` afterwards. */
  parseFile?: ParseFile;
  /** File types the drop zone accepts; default csv, tsv, xls, and xlsx. Pair it with `parseFile` for other types. */
  accept?: DropzoneAccept;
  /** Decodes a CSV file with this `TextDecoder` label instead of UTF-8. A label outside `IMPORT_CSV_ENCODINGS` shows `labels.io.errorParseFailed`. */
  csvEncoding?: ImportCsvEncoding;
  /** Rewrites or drops the data rows before they are mapped. `false` cancels the import quietly. The result is checked against `importLimits`. */
  processImportRows?: ProcessImportRows;
  /** Parses one cell instead of the column's `fromText`. Default: the grid's `processCellFromClipboard`, then `fromText`. The value still passes `column.validate`. */
  processCellFromText?: ProcessCellFromText<TData>;
  /** A file to load when the dialog opens, as if the user had chosen it. */
  file?: File;
  /** Checks the built rows on your server before `onImport` runs. An answer without `rejected` entries goes on to `onImport`; an answer with entries opens a check step that lists them, with the buttons "Import anyway" and "Back". A throw, a rejection, or an answer in another shape shows `labels.io.checkFailed`. The answer is read with bounds: 1,000 entries, a row index inside the rows, messages cut at 200 characters. `ctx.signal` aborts when the user cancels, the dialog closes, or a new file loads. Absent: no check. */
  checkImport?: CheckImport<TData>;
};

/** The rows held back while the user reads the check step. */
type CheckStep<TData> = {
  rows: TData[];
  rejected: readonly ImportRejectedCell[];
  flagged: readonly ImportRejectedCell[];
  source: ImportSource;
  refusals: ImportCheckRefusal[];
  more: number;
  summary?: ImportCheckSummary;
};

/** Refusals the check step lists. */
const CHECK_STEP_ROWS = 100;

/**
 * File-picker -> preview -> column-mapping -> confirm dialog. Parses via
 * {@link useDataGridImportPreview}, builds `TData` rows via {@link buildImportedRows} through each mapped
 * column's cell-type `fromText` + `validate`, then hands the rows to `onImport`. Without `onImport` it
 * appends them through `commitChange`; a replace or a server call passes `onImport`. A cell that
 * fails `validate` is cleared (via its cell type's `clearValue()`), not dropped as a row; the
 * rejected cells are listed in {@link buildImportedRows}'s `rejected` result.
 */
export function DataGridImportDialog<TData>(props: DataGridImportDialogProps<TData>): ReactNode {
  const { open, onOpenChange, createRow, onImport, onImportError, importDefaults, importLimits, parseFile, accept = IMPORT_ACCEPT, csvEncoding, processImportRows, processCellFromText, file, className, checkImport } = props;
  const maxFileBytes = resolveImportLimits(importLimits).maxFileBytes;
  const labels = useDataGridLabels();
  const actions = useDataGridActions();
  const storeApi = useDataGridStoreApi();
  const commitWithFlags = useDataGridFlaggedCommit();
  const allColumns = useDataGridAllColumns<TData>();
  const [isValidating, setIsValidating] = useState(false);
  /** Generation guard for a held async import: a newer confirm, or closing the dialog, drops the older batch. */
  const confirmTokenRef = useRef(0);
  /** Aborts the in-flight chunked build (large sync imports and async-schema imports alike) when Cancel is clicked or the dialog closes. */
  const abortControllerRef = useRef<AbortController | null>(null);
  const headerRowId = useId();
  const confirmButtonRef = useRef<HTMLButtonElement | null>(null);
  const returnFocusRef = useRef(false);
  const [checkStep, setCheckStep] = useState<CheckStep<TData> | null>(null);
  const { preview, error, isParsing, loadFile, setHasHeaderRow, setDelimiter, setSheetName, setMapping, reset, previewRows, importRows, build } =
    useDataGridImportPreview({ columnFallback: labels.io.columnFallback, defaults: importDefaults, limits: importLimits, parseFile, csvEncoding });
  useDataGridMarkGatePending("import", isParsing || isValidating);
  // Base UI's SelectValue shows the raw value until the popup mounts its items, unless the root gets `items`
  const delimiterItems = DELIMITER_OPTIONS.map((option) => ({ value: option.value, label: labels.io[option.labelKey] }));
  const mappingItems = [{ value: SKIP_VALUE, label: labels.io.skipColumn }, ...allColumns.map((column) => ({ value: column.id, label: columnLabelText(column) }))];

  useEffect(() => {
    if (open) return;
    confirmTokenRef.current += 1;
    abortControllerRef.current?.abort();
    setIsValidating(false);
    setUnsupportedDrop(false);
    setRejectedCount(0);
    setMergeFailed(false);
    setMergeMessage(null);
    setBuildError(null);
    setCheckStep(null);
    reset();
  }, [open, reset]);

  useEffect(() => {
    if (checkStep || !returnFocusRef.current) return;
    returnFocusRef.current = false;
    confirmButtonRef.current?.focus();
  }, [checkStep]);

  useEffect(
    () => () => {
      confirmTokenRef.current += 1;
      abortControllerRef.current?.abort();
    },
    [],
  );

  const [unsupportedDrop, setUnsupportedDrop] = useState(false);
  const onFile = useCallback(
    (file: File) => {
      confirmTokenRef.current += 1;
      abortControllerRef.current?.abort();
      setIsValidating(false);
      setCheckStep(null);
      setUnsupportedDrop(false);
      const targets: ImportTargetColumn[] = allColumns.map((c) => ({ id: c.id, headerText: c.headerText, header: c.header }));
      setRejectedCount(0);
      setMergeFailed(false);
      setMergeMessage(null);
      setBuildError(null);
      void loadFile(file, targets);
    },
    [allColumns, loadFile],
  );

  const loadedPropFileRef = useRef<File | null>(null);
  useEffect(() => {
    if (!open || !file || loadedPropFileRef.current === file) return;
    loadedPropFileRef.current = file;
    onFile(file);
  }, [open, file, onFile]);
  useEffect(() => {
    if (!open) loadedPropFileRef.current = null;
  }, [open]);

  const onDropFiles = useCallback(
    (acceptedFiles: File[], rejections: DropzoneRejection[]) => {
      // a maxSize rejection is re-routed through loadFile so the parse's own size check surfaces the dialog's too-large error
      const file = acceptedFiles[0] ?? (rejections.some((r) => r.reasons.includes("maxSize")) ? rejections[0]?.file : undefined);
      if (file) onFile(file);
      else if (rejections.some((r) => r.reasons.includes("accept"))) setUnsupportedDrop(true);
    },
    [onFile],
  );

  /** Rejected-cell count from the last confirmed build; non-zero keeps the dialog open so the warning is visible. */
  const [rejectedCount, setRejectedCount] = useState(0);
  /** True when `onImport` rejected; the dialog stays open and the import can be retried. */
  const [mergeFailed, setMergeFailed] = useState(false);
  /** Message of the last `onImport` rejection, when it had one. */
  const [mergeMessage, setMergeMessage] = useState<string | null>(null);
  /** Error key of a row hook or build that failed before `onImport`. */
  const [buildError, setBuildError] = useState<ImportErrorKey | "importBuildFailed" | "checkFailed" | null>(null);
  const warnedMissingOnImportRef = useRef(false);
  const appendRows = useCallback(
    (rows: TData[], flagged: readonly ImportRejectedCell[]) => {
      const state = storeApi.getState();
      const block = appendBlockOf(state) ?? (hasUnloadedRows(state.data) ? "importNeedsOnImport" : null);
      if (block) {
        if (block === "importNeedsOnImport" && isDev() && !warnedMissingOnImportRef.current) {
          warnedMissingOnImportRef.current = true;
          console.warn("[data-grid-io] this grid holds a window of its result; pass onImport to send the rows to your server");
        }
        throw new Error(labels.io[block]);
      }
      const start = state.data.length;
      const flags = flagged.flatMap(({ rowIndex, gridColumnId, message }) => {
        const row = rows[rowIndex];
        return row === undefined ? [] : [{ rowId: state.getRowId(row, start + rowIndex), columnId: gridColumnId, message: message ?? "" }];
      });
      commitWithFlags(
        {
          source: "import",
          ops: rows.map((row, offset) => ({ type: "insert" as const, rowId: state.getRowId(row, start + offset), row, index: start + offset })),
        },
        flags,
      );
    },
    [commitWithFlags, storeApi, labels],
  );
  const finish = useCallback(
    (rows: TData[], rejected: readonly ImportRejectedCell[], flagged: readonly ImportRejectedCell[], source: ImportSource) => {
      setMergeFailed(false);
      setMergeMessage(null);
      setIsValidating(true);
      const token = ++confirmTokenRef.current;
      const signal = abortControllerRef.current?.signal ?? new AbortController().signal;
      void Promise.resolve()
        .then(() => (onImport ? onImport(rows, { signal, rejected, flagged, ...source }) : appendRows(rows, flagged)))
        .then(() => {
          if (confirmTokenRef.current === token) actions.clearSelection();
        })
        .then(
          () => {
            if (confirmTokenRef.current !== token) return;
            setIsValidating(false);
            setCheckStep(null);
            if (rejected.length > 0) {
              setRejectedCount(rejected.length);
              return;
            }
            onOpenChange(false);
          },
          (error) => {
            if (confirmTokenRef.current !== token) return;
            setIsValidating(false);
            setMergeFailed(true);
            setMergeMessage(error instanceof Error && error.message !== "" ? error.message.slice(0, MAX_ERROR_MESSAGE_LENGTH) : null);
            if (onImportError) {
              try {
                onImportError(error);
              } catch (callbackError) {
                if (isDev()) console.warn("[data-grid-io] onImportError threw", callbackError);
              }
            } else if (isDev() && onImport) console.warn("[data-grid-io] onImport rejected; the dialog stays open", error);
          },
        );
    },
    [onImport, onImportError, appendRows, actions, onOpenChange],
  );

  const onConfirm = useCallback(() => {
    if (!preview) return;
    const state = storeApi.getState();
    const abortController = new AbortController();
    abortControllerRef.current = abortController;
    setBuildError(null);
    const clipboardParse = state.processCellFromClipboard as ((text: string, ctx: { row: TData; column: unknown; fromText: (text: string) => unknown }) => unknown) | undefined;
    const cellParser: ProcessCellFromText<TData> | undefined =
      processCellFromText ?? (clipboardParse ? (text, ctx) => clipboardParse(text, { row: ctx.row, column: ctx.column, fromText: ctx.fromText }) : undefined);
    // state.cellTypes comes back from the generic-erased store (TData = unknown, see core store.tsx's InternalSyncProps comment); re-widened here to this dialog's own TData. allColumns is already TData-typed via useDataGridAllColumns<TData>() above.
    const source: ImportSource = { fileName: preview.fileName, sheetName: preview.sheetName, mapping: preview.mapping };
    const token = ++confirmTokenRef.current;
    const fail = (reason: unknown) => {
      if (confirmTokenRef.current !== token) return;
      setIsValidating(false);
      if (reason instanceof Error && reason.message === IMPORT_CANCELLED_MESSAGE) return;
      const key = importErrorKey(reason);
      if (key === null) {
        if (!abortController.signal.aborted) setBuildError("importBuildFailed");
        return;
      }
      setBuildError(key === "errorTooManyCells" || key === "errorNoRows" ? key : "importBuildFailed");
    };
    const built = build<TData>({
      columns: allColumns,
      // The store erases TData; the cast re-widens cellTypes to this dialog's TData.
      cellTypes: state.cellTypes as never,
      createRow,
      signal: abortController.signal,
      processImportRows,
      processCellFromText: cellParser,
      checkImport,
      existingRows: onImport ? undefined : (state.data as TData[]),
      validateRow: onImport ? (state.validateRow as BuildImportedRowsOptions<TData>["validateRow"]) : undefined,
      getRowId: (row, index) => state.getRowId(row, state.data.length + index),
    });
    // The dialog stays open with Import disabled while the build runs (chunked so it can repaint and Cancel can land),
    // and closes when the last verdict is in, or drops the batch silently if Cancel/close beat it.
    setIsValidating(true);
    void built.then((result) => {
      if (confirmTokenRef.current !== token) return; // superseded by a newer confirm, or the dialog reset
      setIsValidating(false);
      if (result === null) return;
      const { check } = result;
      if (check?.status === "failed") return setBuildError("checkFailed");
      if (check && check.refusals.length > 0) return setCheckStep({ rows: result.rows, rejected: result.rejected, flagged: result.flagged, source, refusals: check.refusals, more: check.more, summary: check.summary });
      finish(result.rows, result.rejected, result.flagged, source);
    }, fail);
  }, [preview, build, allColumns, storeApi, createRow, finish, processImportRows, processCellFromText, onImport, checkImport]);

  const backFromCheck = useCallback(() => {
    returnFocusRef.current = true;
    setCheckStep(null);
  }, []);

  const onCancel = useCallback(() => {
    abortControllerRef.current?.abort();
    onOpenChange(false);
  }, [onOpenChange]);

  const importBlock = useImportBlock(onImport, open);
  const acceptedTypesLabel = labels.io.dropzoneDescription(acceptedTypeNames(accept), labels.io.maxFileSize(maxFileBytes));

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className={cn("max-h-[80vh] min-w-0 overflow-y-auto sm:max-w-2xl", className)}>
        <DialogHeader>
          <DialogTitle>{checkStep ? labels.io.checkStepTitle : labels.io.importDialogTitle}</DialogTitle>
          <DialogDescription>{labels.io.importDialogDescription}</DialogDescription>
        </DialogHeader>

        <div className="flex min-w-0 flex-col gap-3">
          {checkStep ? null : preview ? (
            <Dropzone compact accept={accept} accessibleDescription={acceptedTypesLabel} maxFiles={1} maxSize={maxFileBytes} onDrop={onDropFiles} aria-label={labels.io.chooseFile}>
              <Paperclip className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
              <span className="min-w-0 flex-1 truncate text-sm text-foreground">{preview.fileName}</span>
              <span className="shrink-0 text-xs text-muted-foreground">{labels.io.replaceFile}</span>
            </Dropzone>
          ) : (
            <Dropzone accept={accept} accessibleDescription={acceptedTypesLabel} maxFiles={1} maxSize={maxFileBytes} onDrop={onDropFiles} aria-label={labels.io.chooseFile}>
              <DropzoneEmptyState title={labels.io.chooseFile} description={labels.io.emptyDropzoneCaption(labels.io.maxFileSize(maxFileBytes))} />
            </Dropzone>
          )}

          {importBlock && <p role="alert" className="text-sm text-destructive">{labels.io[importBlock]}</p>}

          {unsupportedDrop && <p role="alert" className="text-sm text-destructive">{labels.io.errorUnsupportedFile}</p>}

          {error && <p role="alert" className="text-sm text-destructive">{labels.io[error]}</p>}

          {rejectedCount > 0 && <p role="alert" className="text-sm text-destructive">{labels.io.importRejectedCells(rejectedCount)}</p>}

          {buildError && <p role="alert" className="text-sm text-destructive">{labels.io[buildError]}</p>}

          {mergeFailed && (
            <p role="alert" className="text-sm text-destructive">
              {mergeMessage ? labels.io.importFailedWithMessage(mergeMessage) : labels.io.importMergeFailed}
            </p>
          )}

          {checkStep && (
            <div className="flex min-w-0 flex-col gap-2">
              <p className="text-sm font-medium text-foreground">{labels.io.checkSummary({ refused: checkStep.refusals.length + checkStep.more, ...checkStep.summary })}</p>
              <div className="min-w-0 overflow-hidden rounded-md border border-border">
                <Table>
                  <TableHeader>
                    <TableRow className="hover:bg-transparent">
                      <TableHead>{labels.io.checkRowHeading}</TableHead>
                      <TableHead>{labels.io.checkColumnHeading}</TableHead>
                      <TableHead>{labels.io.checkMessageHeading}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {checkStep.refusals.slice(0, CHECK_STEP_ROWS).map((refusal, index) => {
                      const column = allColumns.find((candidate) => candidate.id === refusal.columnId);
                      return (
                        <TableRow key={index} className="hover:bg-transparent">
                          <TableCell className="p-1.5">{refusal.rowIndex + 1}</TableCell>
                          <TableCell className="p-1.5">{column ? columnLabelText(column) : ""}</TableCell>
                          <TableCell className="whitespace-normal p-1.5 text-muted-foreground">{refusal.message ?? ""}</TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </div>
              {checkStep.refusals.length + checkStep.more > CHECK_STEP_ROWS && (
                <span className="text-xs text-muted-foreground">{labels.io.checkAndMore(checkStep.refusals.length + checkStep.more - CHECK_STEP_ROWS)}</span>
              )}
            </div>
          )}

          {preview && !checkStep && (
            <>
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                  <Checkbox id={headerRowId} checked={preview.hasHeaderRow} onCheckedChange={(checked) => setHasHeaderRow(checked === true)} />
                  <Label htmlFor={headerRowId}>{labels.io.hasHeaderRow}</Label>
                </div>
                {preview.delimiter !== undefined && (
                  <label className="flex items-center gap-2 text-sm text-foreground">
                    {labels.io.delimiter}
                    <Select items={delimiterItems} value={preview.delimiter} onValueChange={(value) => void setDelimiter(value as CsvDelimiter)}>
                      <SelectTrigger className="w-36" size="sm" aria-label={labels.io.delimiter}>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {delimiterItems.map((item) => (
                          <SelectItem key={item.value} value={item.value}>
                            {item.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </label>
                )}
                {preview.sheetNames !== undefined && preview.sheetNames.length > 1 && (
                  <label className="flex items-center gap-2 text-sm text-foreground">
                    {labels.io.sheet}
                    <Select value={preview.sheetName ?? preview.sheetNames[0]} onValueChange={(value) => void setSheetName(value as string)}>
                      <SelectTrigger className="w-40" size="sm" aria-label={labels.io.sheet}>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {preview.sheetNames.map((name) => (
                          <SelectItem key={name} value={name} title={name}>
                            {name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </label>
                )}
              </div>

              <div className="flex min-w-0 flex-col gap-1">
                <span className="text-sm font-medium text-foreground">{labels.io.mapColumns}</span>
                <div className="min-w-0 overflow-hidden rounded-md border border-border">
                  {/* fixed layout gives every column an identical track — keeps selects and preview cells aligned */}
                  <Table className="table-fixed" style={{ minWidth: `${preview.importHeaders.length * 9}rem` }}>
                    <TableHeader>
                      <TableRow className="hover:bg-transparent has-aria-expanded:bg-transparent">
                        {preview.importHeaders.map((header, importColumnIndex) => {
                          const currentGridColumnId = preview.mapping[importColumnIndex]?.gridColumnId ?? null;
                          // one source per grid column: a column mapped elsewhere is disabled
                          const takenElsewhere = new Set(
                            preview.mapping
                              .filter((m) => m.importColumnIndex !== importColumnIndex && m.gridColumnId !== null)
                              .map((m) => m.gridColumnId),
                          );
                          return (
                            <TableHead key={importColumnIndex} className="h-auto bg-muted/50 p-1.5 align-top whitespace-normal">
                              <div className="mb-1 truncate" title={header}>
                                {header}
                              </div>
                              <div className="flex items-center gap-1">
                                <Select
                                  items={mappingItems}
                                  value={currentGridColumnId ?? SKIP_VALUE}
                                  onValueChange={(value) =>
                                    setMapping(importColumnIndex, value === SKIP_VALUE || value === null ? null : value)
                                  }
                                >
                                  <SelectTrigger className="w-full" size="sm" aria-label={labels.io.mapColumnAriaLabel(header)}>
                                    <SelectValue />
                                  </SelectTrigger>
                                  <SelectContent>
                                    {mappingItems.map((item) => (
                                      <SelectItem key={item.value} value={item.value} disabled={takenElsewhere.has(item.value)}>
                                        {item.label}
                                      </SelectItem>
                                    ))}
                                  </SelectContent>
                                </Select>
                                {currentGridColumnId !== null && (
                                  <Button
                                    type="button"
                                    variant="ghost"
                                    size="icon"
                                    className="size-7 shrink-0"
                                    aria-label={labels.io.skipColumnQuick}
                                    onClick={() => setMapping(importColumnIndex, null)}
                                  >
                                    <X className="size-3.5" />
                                  </Button>
                                )}
                              </div>
                            </TableHead>
                          );
                        })}
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {previewRows.map((row, rowIndex) => (
                        <TableRow key={rowIndex} className="hover:bg-transparent">
                          {preview.importHeaders.map((_, columnIndex) => (
                            <TableCell key={columnIndex} className="truncate p-1.5 text-muted-foreground" title={row[columnIndex] ?? ""}>
                              {row[columnIndex] ?? ""}
                            </TableCell>
                          ))}
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
                {preview.importHeaders.length > 1 && (
                  <span className="text-xs text-muted-foreground">{labels.io.mapColumnsHint}</span>
                )}
                <span className="text-xs text-muted-foreground">
                  {labels.io.previewTruncated(previewRows.length, importRows.length)}
                </span>
              </div>
            </>
          )}
        </div>

        <DialogFooter>
          {checkStep ? (
            <Fragment key="check">
              <Button type="button" variant="outline" onClick={backFromCheck} autoFocus>
                {labels.io.back}
              </Button>
              <Button type="button" onClick={() => finish(checkStep.rows, checkStep.rejected, checkStep.flagged, checkStep.source)} disabled={isValidating}>
                {labels.io.importAnyway}
              </Button>
            </Fragment>
          ) : (
            <Fragment key="confirm">
          <Button type="button" variant="outline" onClick={onCancel}>
            {labels.io.cancel}
          </Button>
            <Button ref={confirmButtonRef} type="button" onClick={onConfirm} disabled={!preview || importBlock !== null || importRows.length === 0 || isParsing || isValidating || rejectedCount > 0}>
              {labels.io.import}
            </Button>
            </Fragment>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import { Upload } from "lucide-react";
import { useDataGridLabels } from "@/registry/default/components/data-grid/data-grid";
import { Button } from "@/components/ui/button";
import { DataGridImportDialog, useImportBlock, type DataGridImportDialogProps, type ImportDefaults } from "./import-dialog";

export type { ImportDefaults };

/** Props for {@link DataGridImportButton}: the dialog's props except the open state, plus `className`. */
export type DataGridImportButtonProps<TData> = Omit<DataGridImportDialogProps<TData>, "open" | "onOpenChange" | "className"> & {
  className?: string;
};

/**
 * Toolbar-slot import trigger: a ghost icon button that opens {@link DataGridImportDialog}.
 * `size-8` + ghost variant matches the toolbar's other icon buttons.
 */
export function DataGridImportButton<TData>(props: DataGridImportButtonProps<TData>): ReactNode {
  const { className, ...dialogProps } = props;
  const labels = useDataGridLabels();
  const [open, setOpen] = useState(false);
  const importBlock = useImportBlock(dialogProps.onImport, true);

  return (
    <>
      <Button type="button" variant="ghost" size="icon" className={className} aria-label={labels.io.importButton} disabled={importBlock !== null} title={importBlock ? labels.io[importBlock] : undefined} onClick={() => setOpen(true)}>
        <Upload />
      </Button>
      <DataGridImportDialog open={open} onOpenChange={setOpen} {...dialogProps} />
    </>
  );
}
